mod nix_parse;
mod analysis;
mod output;

use std::path::{Path, PathBuf};
use std::fs;
use std::io::{self, Write};
use std::process;

fn print_help() {
    println!("Find dead code in .nix files

Usage: deadnix [OPTIONS] [FILE_PATHS]...

Arguments:
  [FILE_PATHS]...  .nix files, or directories with .nix files inside [default: .]

Options:
  -l, --no-lambda-arg                  Don't check lambda parameter arguments
  -L, --no-lambda-pattern-names        Don't check lambda attrset pattern names (don't break nixpkgs callPackage)
  -_, --no-underscore                  Don't check any bindings that start with a _
                                       (Lambda arguments starting with _ are not checked anyway.)
  -W, --warn-used-underscore           Warn if bindings are referenced that start with '_'
  -q, --quiet                          Don't print dead code report
  -e, --edit                           Remove unused code and write to source file
  -h, --hidden                         Recurse into hidden subdirectories and process hidden .*.nix files
      --help                           
  -f, --fail                           Exit with 1 if unused code has been found
  -o, --output-format <OUTPUT_FORMAT>  Output format to use [default: human-readable] [possible values: human-readable, json]
      --exclude <EXCLUDES>...          Files to exclude from analysis
  -V, --version                        Print version");
}

fn print_version() {
    println!("deadnix 1.3.1");
}

#[derive(Debug, Clone)]
struct Config {
    no_lambda_arg: bool,
    no_lambda_pattern_names: bool,
    no_underscore: bool,
    warn_used_underscore: bool,
    quiet: bool,
    edit: bool,
    hidden: bool,
    fail: bool,
    output_format: OutputFormat,
    excludes: Vec<PathBuf>,
    file_paths: Vec<PathBuf>,
}

#[derive(Debug, Clone, PartialEq)]
enum OutputFormat {
    HumanReadable,
    Json,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut config = Config {
        no_lambda_arg: false,
        no_lambda_pattern_names: false,
        no_underscore: false,
        warn_used_underscore: false,
        quiet: false,
        edit: false,
        hidden: false,
        fail: false,
        output_format: OutputFormat::HumanReadable,
        excludes: Vec::new(),
        file_paths: Vec::new(),
    };

    let mut i = 1;
    let mut collecting_excludes = false;
    let mut after_double_dash = false;

    while i < args.len() {
        let arg = &args[i];

        if !after_double_dash && arg == "--" {
            after_double_dash = true;
            collecting_excludes = false;
            i += 1;
            continue;
        }

        if after_double_dash {
            config.file_paths.push(PathBuf::from(arg));
            i += 1;
            continue;
        }

        if collecting_excludes {
            if arg.starts_with('-') {
                collecting_excludes = false;
                // Fall through to process as option
            } else {
                config.excludes.push(PathBuf::from(arg));
                i += 1;
                continue;
            }
        }

        match arg.as_str() {
            "--help" => {
                print_help();
                process::exit(0);
            }
            "-V" | "--version" => {
                print_version();
                process::exit(0);
            }
            "-l" | "--no-lambda-arg" => {
                config.no_lambda_arg = true;
            }
            "-L" | "--no-lambda-pattern-names" => {
                config.no_lambda_pattern_names = true;
            }
            "-_" | "--no-underscore" => {
                config.no_underscore = true;
            }
            "-W" | "--warn-used-underscore" => {
                config.warn_used_underscore = true;
            }
            "-q" | "--quiet" => {
                config.quiet = true;
            }
            "-e" | "--edit" => {
                config.edit = true;
            }
            "-h" | "--hidden" => {
                config.hidden = true;
            }
            "-f" | "--fail" => {
                config.fail = true;
            }
            "--exclude" => {
                collecting_excludes = true;
            }
            s if s.starts_with("--exclude=") => {
                let val = &s["--exclude=".len()..];
                config.excludes.push(PathBuf::from(val));
            }
            "-o" | "--output-format" => {
                i += 1;
                if i < args.len() {
                    match args[i].as_str() {
                        "human-readable" => config.output_format = OutputFormat::HumanReadable,
                        "json" => config.output_format = OutputFormat::Json,
                        other => {
                            eprintln!("error: invalid value '{}' for '--output-format <OUTPUT_FORMAT>'", other);
                            eprintln!("  [possible values: human-readable, json]");
                            process::exit(2);
                        }
                    }
                }
            }
            s if s.starts_with("--output-format=") => {
                let val = &s["--output-format=".len()..];
                match val {
                    "human-readable" => config.output_format = OutputFormat::HumanReadable,
                    "json" => config.output_format = OutputFormat::Json,
                    other => {
                        eprintln!("error: invalid value '{}' for '--output-format <OUTPUT_FORMAT>'", other);
                        eprintln!("  [possible values: human-readable, json]");
                        process::exit(2);
                    }
                }
            }
            s if s.starts_with('-') && !s.starts_with("--") => {
                // Short flags combined
                let chars: Vec<char> = s[1..].chars().collect();
                let mut j = 0;
                while j < chars.len() {
                    match chars[j] {
                        'l' => config.no_lambda_arg = true,
                        'L' => config.no_lambda_pattern_names = true,
                        '_' => config.no_underscore = true,
                        'W' => config.warn_used_underscore = true,
                        'q' => config.quiet = true,
                        'e' => config.edit = true,
                        'h' => config.hidden = true,
                        'f' => config.fail = true,
                        'o' => {
                            // next argument
                            let val = if j + 1 < chars.len() {
                                let rest: String = chars[j+1..].iter().collect();
                                j = chars.len() - 1;
                                rest
                            } else {
                                i += 1;
                                args.get(i).cloned().unwrap_or_default()
                            };
                            match val.as_str() {
                                "human-readable" => config.output_format = OutputFormat::HumanReadable,
                                "json" => config.output_format = OutputFormat::Json,
                                other => {
                                    eprintln!("error: invalid value '{}' for '--output-format <OUTPUT_FORMAT>'", other);
                                    process::exit(2);
                                }
                            }
                        }
                        _ => {
                            eprintln!("error: unrecognized flag '{}'", s);
                            process::exit(2);
                        }
                    }
                    j += 1;
                }
            }
            _ => {
                config.file_paths.push(PathBuf::from(arg));
            }
        }

        i += 1;
    }

    // Default: use current directory if no paths given
    if config.file_paths.is_empty() {
        config.file_paths.push(PathBuf::from("."));
    }

    // Expand file paths to actual .nix files
    let nix_files = collect_nix_files(&config);

    let no_color = std::env::var("NO_COLOR").is_ok();

    let mut found_any = false;

    for file_path in &nix_files {
        let content = match fs::read_to_string(file_path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Error reading {}: {}", file_path.display(), e);
                continue;
            }
        };

        let diagnostics = analysis::analyze_file(
            &content,
            &config,
        );

        if diagnostics.is_empty() {
            continue;
        }

        found_any = true;

        if !config.quiet {
            match config.output_format {
                OutputFormat::HumanReadable => {
                    output::print_human_readable(&diagnostics, file_path, &content, no_color);
                }
                OutputFormat::Json => {
                    output::print_json(&diagnostics, file_path);
                }
            }
        }

        if config.edit {
            let new_content = analysis::edit_file(&content, &diagnostics);
            if let Err(e) = fs::write(file_path, &new_content) {
                eprintln!("Error writing {}: {}", file_path.display(), e);
            }
        }
    }

    if found_any && config.fail {
        process::exit(1);
    }
}

fn collect_nix_files(config: &Config) -> Vec<PathBuf> {
    let mut files = Vec::new();

    for path in &config.file_paths {
        let path = path.as_path();
        if path.is_file() {
            if is_nix_file(path, config.hidden) && !is_excluded(path, &config.excludes) {
                files.push(path.to_path_buf());
            }
        } else if path.is_dir() {
            collect_dir_files(path, &mut files, config);
        }
    }

    files
}

fn is_nix_file(path: &Path, hidden: bool) -> bool {
    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
        if !hidden && name.starts_with('.') {
            return false;
        }
        name.ends_with(".nix")
    } else {
        false
    }
}

fn is_excluded(path: &Path, excludes: &[PathBuf]) -> bool {
    let canonical = path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
    for excl in excludes {
        let excl_canonical = excl.canonicalize().unwrap_or_else(|_| excl.to_path_buf());
        if canonical == excl_canonical {
            return true;
        }
    }
    false
}

fn collect_dir_files(dir: &Path, files: &mut Vec<PathBuf>, config: &Config) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut entries: Vec<_> = entries
        .filter_map(|e| e.ok())
        .collect();
    entries.sort_by_key(|e| e.file_name());

    for entry in entries {
        let path = entry.path();
        let name = entry.file_name();
        let name_str = name.to_string_lossy();

        if path.is_dir() {
            if !config.hidden && name_str.starts_with('.') {
                continue;
            }
            collect_dir_files(&path, files, config);
        } else if path.is_file() {
            if !config.hidden && name_str.starts_with('.') {
                continue;
            }
            if name_str.ends_with(".nix") && !is_excluded(&path, &config.excludes) {
                files.push(path);
            }
        }
    }
}
