                        other => {
                            eprintln!("error: invalid value '{}' for '--output-format <OUTPUT_FORMAT>'", other);
                            eprintln!("  [possible values: human-readable, json]");
                            process::exit(2);
                        }
                    }
                }
            }
            s if s.starts_with("--output-format=") => {
                let val = &s["--output-format=".len()..];
                match val {
                    "human-readable" => config.output_format = OutputFormat::HumanReadable,
                    "json" => config.output_format = OutputFormat::Json,
                    other => {
                        eprintln!("error: invalid value '{}' for '--output-format <OUTPUT_FORMAT>'", other);
                        eprintln!("  [possible values: human-readable, json]");
                        process::exit(2);
                    }
                }
            }
            s if s.starts_with('-') && !s.starts_with("--") => {
                // Short flags combined
                let chars: Vec<char> = s[1..].chars().collect();
                let mut j = 0;
                while j < chars.len() {
                    match chars[j] {
                        'l' => config.no_lambda_arg = true,
                        'L' => config.no_lambda_pattern_names = true,
                        '_' => config.no_underscore = true,
                        'W' => config.warn_used_underscore = true,
                        'q' => config.quiet = true,
                        'e' => config.edit = true,
                        'h' => config.hidden = true,
                        'f' => config.fail = true,
                        'o' => {
                            // next argument
                            let val = if j + 1 < chars.len() {
                                let rest: String = chars[j+1..].iter().collect();
                                j = chars.len() - 1;
                                rest
                            } else {
                                i += 1;
                                args.get(i).cloned().unwrap_or_default()
                            };
                            match val.as_str() {
                                "human-readable" => config.output_format = OutputFormat::HumanReadable,
                                "json" => config.output_format = OutputFormat::Json,
                                other => {
                                    eprintln!("error: invalid value '{}' for '--output-format <OUTPUT_FORMAT>'", other);
                                    process::exit(2);
                                }
                            }
                        }
                        _ => {
                            eprintln!("error: unrecognized flag '{}'", s);
                            process::exit(2);
                        }
                    }
                    j += 1;
                }
            }
            _ => {
                config.file_paths.push(PathBuf::from(arg));
            }
        }

        i += 1;
    }

    // Default: use current directory if no paths given
    if config.file_paths.is_empty() {
        config.file_paths.push(PathBuf::from("."));
    }

    // Expand file paths to actual .nix files
    let nix_files = collect_nix_files(&config);

    let no_color = std::env::var("NO_COLOR").is_ok();

    let mut found_any = false;

    for file_path in &nix_files {
        let content = match fs::read_to_string(file_path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Error reading {}: {}", file_path.display(), e);
                continue;
            }
        };

        let diagnostics = analysis::analyze_file(
            &content,
            &config,
        );

        if diagnostics.is_empty() {
            continue;
        }

        found_any = true;

        if !config.quiet {
            match config.output_format {
                OutputFormat::HumanReadable => {
                    output::print_human_readable(&diagnostics, file_path, &content, no_color);
                }
                OutputFormat::Json => {
                    output::print_json(&diagnostics, file_path);
                }
            }
        }

        if config.edit {
            let new_content = analysis::edit_file(&content, &diagnostics);
            if let Err(e) = fs::write(file_path, &new_content) {
                eprintln!("Error writing {}: {}", file_path.display(), e);
            }
        }
    }

    if found_any && config.fail {
        process::exit(1);
    }
}

fn collect_nix_files(config: &Config) -> Vec<PathBuf> {
    let mut files = Vec::new();

    for path in &config.file_paths {
        let path = path.as_path();
        if path.is_file() {
            if is_nix_file(path, config.hidden) && !is_excluded(path, &config.excludes) {
                files.push(path.to_path_buf());
            }
        } else if path.is_dir() {
            collect_dir_files(path, &mut files, config);
        }
    }

    files
}

fn is_nix_file(path: &Path, hidden: bool) -> bool {
    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
        if !hidden && name.starts_with('.') {
            return false;
        }
        name.ends_with(".nix")
    } else {
        false
    }
}

fn is_excluded(path: &Path, excludes: &[PathBuf]) -> bool {
    let canonical = path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
    for excl in excludes {
        let excl_canonical = excl.canonicalize().unwrap_or_else(|_| excl.to_path_buf());
        if canonical == excl_canonical {
            return true;
        }
    }
    false
}

fn collect_dir_files(dir: &Path, files: &mut Vec<PathBuf>, config: &Config) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut entries: Vec<_> = entries
        .filter_map(|e| e.ok())
        .collect();
    entries.sort_by_key(|e| e.file_name());

    for entry in entries {
        let path = entry.path();
        let name = entry.file_name();
        let name_str = name.to_string_lossy();

        if path.is_dir() {
            if !config.hidden && name_str.starts_with('.') {
                continue;
            }
            collect_dir_files(&path, files, config);
        } else if path.is_file() {
            if !config.hidden && name_str.starts_with('.') {
                continue;
            }
            if name_str.ends_with(".nix") && !is_excluded(&path, &config.excludes) {
                files.push(path);
            }
        }
    }
}
