/// Nix expression parser
/// Produces an AST for dead code analysis

#[derive(Debug, Clone, PartialEq)]
pub struct Span {
    pub start: usize,  // byte offset
    pub end: usize,    // byte offset (exclusive)
}

impl Span {
    pub fn new(start: usize, end: usize) -> Self {
        Span { start, end }
    }
}

#[derive(Debug, Clone)]
pub struct Ident {
    pub name: String,
    pub span: Span,
}

/// A binding in a let expression
#[derive(Debug, Clone)]
pub enum LetBinding {
    /// name = expr;
    Plain {
        name: Ident,
        value: Box<Expr>,
        /// true if there's a # deadnix: skip comment before this binding
        skip: bool,
    },
    /// inherit (expr) name1 name2;
    Inherit {
        from: Option<Box<Expr>>,
        names: Vec<Ident>,
        /// true if there's a # deadnix: skip comment before this binding
