pub struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str) -> Self {
        Parser {
            src: src.as_bytes(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn peek2(&self) -> Option<u8> {
        self.src.get(self.pos + 1).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let b = self.src.get(self.pos).copied();
        if b.is_some() {
            self.pos += 1;
        }
        b
    }

    fn skip_whitespace_and_comments(&mut self) {
        loop {
            // Skip whitespace
            while self.pos < self.src.len() {
                let b = self.src[self.pos];
                if b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' {
                    self.pos += 1;
                } else {
                    break;
                }
            }

            // Skip line comments
            if self.pos + 1 < self.src.len() && self.src[self.pos] == b'#' {
                while self.pos < self.src.len() && self.src[self.pos] != b'\n' {
                    self.pos += 1;
                }
                continue;
            }

            // Skip block comments
            if self.pos + 1 < self.src.len() && self.src[self.pos] == b'/' && self.src[self.pos+1] == b'*' {
                self.pos += 2;
                while self.pos + 1 < self.src.len() {
                    if self.src[self.pos] == b'*' && self.src[self.pos+1] == b'/' {
                        self.pos += 2;
                        break;
                    }
                    self.pos += 1;
                }
                continue;
            }

            break;
        }
    }

    /// Check if there's a "# deadnix: skip" comment before current position
    /// Returns true if the last non-empty comment before current pos is deadnix: skip
    fn check_deadnix_skip_before(&self, search_from: usize) -> bool {
        // Look backwards from search_from to find a comment on the previous line
        // Actually we need to look at what's between the previous binding end and this one
        // We'll do a forward scan from search_from
        let mut pos = search_from;
        let src = self.src;

        while pos < src.len() {
            // Skip whitespace (but not newlines that separate lines)
            while pos < src.len() && (src[pos] == b' ' || src[pos] == b'\t') {
                pos += 1;
            }

            if pos < src.len() && src[pos] == b'#' {
                // Check if this is a deadnix: skip comment
                let start = pos;
                while pos < src.len() && src[pos] != b'\n' {
                    pos += 1;
                }
                let comment = std::str::from_utf8(&src[start..pos]).unwrap_or("");
                if comment.contains("deadnix: skip") {
                    return true;
                }
                if pos < src.len() {
                    pos += 1; // skip newline
                }
                continue;
            }

            if pos < src.len() && src[pos] == b'\n' {
                pos += 1;
                continue;
            }

            if pos + 1 < src.len() && src[pos] == b'/' && src[pos+1] == b'*' {
                pos += 2;
                while pos + 1 < src.len() {
                    if src[pos] == b'*' && src[pos+1] == b'/' {
                        pos += 2;
                        break;
                    }
                    pos += 1;
                }
                continue;
            }

            break;
        }

        false
    }

    /// Parse the comment area before a binding, returning whether there's a deadnix: skip
    fn parse_comment_skip(&mut self) -> bool {
        let start = self.pos;

        // Scan forward through whitespace and comments to find if there's a deadnix: skip
        // that applies to the next binding
        let mut pos = start;
        let src = self.src;
        let mut found_skip = false;
        let mut last_comment_was_skip = false;

        // We do a lookahead scan
        loop {
            while pos < src.len() && (src[pos] == b' ' || src[pos] == b'\t' || src[pos] == b'\r' || src[pos] == b'\n') {
                pos += 1;
            }

            if pos < src.len() && src[pos] == b'#' {
                let start = pos;
                while pos < src.len() && src[pos] != b'\n' {
                    pos += 1;
                }
                let comment = std::str::from_utf8(&src[start..pos]).unwrap_or("");
                last_comment_was_skip = comment.contains("deadnix: skip");
                if last_comment_was_skip {
                    found_skip = true;
                }
                continue;
            }

            if pos + 1 < src.len() && src[pos] == b'/' && src[pos+1] == b'*' {
                pos += 2;
                last_comment_was_skip = false;
                while pos + 1 < src.len() {
                    if src[pos] == b'*' && src[pos+1] == b'/' {
                        pos += 2;
                        break;
                    }
                    pos += 1;
                }
                continue;
            }

            break;
        }

        // The skip applies if the LAST comment before this token was a skip
        // Actually we need to find the last comment in the whitespace area before next token
        // Let's re-do this more carefully
        found_skip && last_comment_was_skip
    }

    fn current_pos(&self) -> usize {
        self.pos
    }

    fn expect(&mut self, expected: &[u8]) -> bool {
        if self.src[self.pos..].starts_with(expected) {
            self.pos += expected.len();
            true
        } else {
            false
        }
    }

    fn starts_with(&self, s: &[u8]) -> bool {
        self.src[self.pos..].starts_with(s)
    }

    fn parse_ident_raw(&mut self) -> Option<String> {
        let start = self.pos;
        if self.pos >= self.src.len() {
            return None;
        }
        let first = self.src[self.pos];
        if !(first.is_ascii_alphabetic() || first == b'_') {
            return None;
        }
        self.pos += 1;
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            if b.is_ascii_alphanumeric() || b == b'_' || b == b'\'' || b == b'-' {
                self.pos += 1;
            } else {
                break;
            }
        }
        Some(std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string())
    }

    pub fn parse_ident(&mut self) -> Option<Ident> {
        let start = self.pos;
        let name = self.parse_ident_raw()?;
        let end = self.pos;
        Some(Ident { name, span: Span::new(start, end) })
    }

    pub fn parse_expr(&mut self) -> Expr {
        self.parse_impl()
    }

    fn parse_impl(&mut self) -> Expr {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        loop {
            self.skip_whitespace_and_comments();
            if self.starts_with(b"||") {
                self.pos += 2;
                let right = self.parse_and();
                left = Expr::BinOp { op: BinOpKind::Or, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_impl_op();
        loop {
            self.skip_whitespace_and_comments();
            if self.starts_with(b"&&") {
                self.pos += 2;
                let right = self.parse_impl_op();
                left = Expr::BinOp { op: BinOpKind::And, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_impl_op(&mut self) -> Expr {
        let left = self.parse_eq();
        self.skip_whitespace_and_comments();
        if self.starts_with(b"->") {
            self.pos += 2;
            let right = self.parse_impl_op();
            Expr::BinOp { op: BinOpKind::Impl, left: Box::new(left), right: Box::new(right) }
        } else {
            left
        }
    }

    fn parse_eq(&mut self) -> Expr {
        let mut left = self.parse_cmp();
        loop {
            self.skip_whitespace_and_comments();
            if self.starts_with(b"==") {
                self.pos += 2;
                let right = self.parse_cmp();
                left = Expr::BinOp { op: BinOpKind::Eq, left: Box::new(left), right: Box::new(right) };
            } else if self.starts_with(b"!=") {
                self.pos += 2;
                let right = self.parse_cmp();
                left = Expr::BinOp { op: BinOpKind::NEq, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut left = self.parse_update();
        loop {
            self.skip_whitespace_and_comments();
            if self.starts_with(b"<=") {
                self.pos += 2;
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Lte, left: Box::new(left), right: Box::new(right) };
            } else if self.starts_with(b">=") {
                self.pos += 2;
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Gte, left: Box::new(left), right: Box::new(right) };
            } else if self.starts_with(b"<") && !self.starts_with(b"<=") {
                // Make sure we don't accidentally parse < for paths like <nixpkgs>
                let next = self.src.get(self.pos+1).copied();
                if next.map_or(false, |b| b.is_ascii_alphanumeric() || b == b'/' || b == b'_' || b == b'.' || b == b'-') {
                    // might be a path or comparison
                    // We'll try comparison
                    self.pos += 1;
                    let right = self.parse_update();
                    left = Expr::BinOp { op: BinOpKind::Lt, left: Box::new(left), right: Box::new(right) };
                } else {
                    break;
                }
            } else if self.starts_with(b">") && !self.starts_with(b">=") {
                self.pos += 1;
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Gt, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_update(&mut self) -> Expr {
        let mut left = self.parse_not();
        loop {
            self.skip_whitespace_and_comments();
            if self.starts_with(b"//") {
                self.pos += 2;
                let right = self.parse_not();
                left = Expr::BinOp { op: BinOpKind::Update, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_not(&mut self) -> Expr {
        self.skip_whitespace_and_comments();
        if self.starts_with(b"!") && !self.starts_with(b"!=") {
            self.pos += 1;
            let expr = self.parse_not();
            Expr::UnaryOp { op: UnaryOpKind::Not, expr: Box::new(expr) }
        } else {
            self.parse_concat()
        }
    }

    fn parse_concat(&mut self) -> Expr {
        let mut left = self.parse_add();
        loop {
            self.skip_whitespace_and_comments();
            if self.starts_with(b"++") {
                self.pos += 2;
                let right = self.parse_concat();
                left = Expr::BinOp { op: BinOpKind::Concat, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_add(&mut self) -> Expr {
        let mut left = self.parse_mul();
        loop {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'+') && self.peek2() != Some(b'+') {
                self.pos += 1;
                let right = self.parse_mul();
                left = Expr::BinOp { op: BinOpKind::Add, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'-') {
                // make sure it's not a negative number or identifier char
                let next = self.src.get(self.pos+1).copied();
                if next.map_or(false, |b| b.is_ascii_alphanumeric() || b == b'"' || b == b'(' || b == b'{' || b == b'[' || b == b'_') {
                    self.pos += 1;
                    let right = self.parse_mul();
                    left = Expr::BinOp { op: BinOpKind::Sub, left: Box::new(left), right: Box::new(right) };
                } else if next == Some(b' ') || next == Some(b'\t') || next == Some(b'\n') {
                    // a - b
                    self.pos += 1;
                    let right = self.parse_mul();
                    left = Expr::BinOp { op: BinOpKind::Sub, left: Box::new(left), right: Box::new(right) };
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        left
    }

    fn parse_mul(&mut self) -> Expr {
        let mut left = self.parse_neg();
        loop {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'*') {
                self.pos += 1;
                let right = self.parse_neg();
                left = Expr::BinOp { op: BinOpKind::Mul, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'/') {
                let next = self.src.get(self.pos+1).copied();
                if next != Some(b'/') && next != Some(b'*') {
                    self.pos += 1;
                    let right = self.parse_neg();
                    left = Expr::BinOp { op: BinOpKind::Div, left: Box::new(left), right: Box::new(right) };
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        left
    }

    fn parse_neg(&mut self) -> Expr {
        self.skip_whitespace_and_comments();
        if self.peek() == Some(b'-') && self.src.get(self.pos+1).map_or(false, |b| !b.is_ascii_digit()) {
            self.pos += 1;
            let expr = self.parse_hasattr();
            Expr::UnaryOp { op: UnaryOpKind::Neg, expr: Box::new(expr) }
        } else {
            self.parse_hasattr()
        }
    }

    fn parse_hasattr(&mut self) -> Expr {
        let expr = self.parse_apply();
        self.skip_whitespace_and_comments();
        if self.peek() == Some(b'?') {
            self.pos += 1;
            self.skip_whitespace_and_comments();
            let attr = self.parse_attr_path();
            Expr::HasAttr { expr: Box::new(expr), attr }
        } else {
            expr
        }
    }

    fn parse_apply(&mut self) -> Expr {
        let mut func = self.parse_select();
        loop {
            self.skip_whitespace_and_comments();
            // Check if next token can start an argument
            if self.can_start_atom() {
                let arg = self.parse_select();
                func = Expr::Apply { func: Box::new(func), arg: Box::new(arg) };
            } else {
                break;
            }
        }
        func
    }

    fn can_start_atom(&self) -> bool {
        match self.peek() {
            None => false,
            Some(b) => match b {
                b'(' | b'"' | b'\'' | b'[' | b'{' => true,
                b'-' => self.src.get(self.pos+1).map_or(false, |b| b.is_ascii_digit()),
                b'/' => {
                    // Could be a path like /foo or ./foo - but NOT operators
                    let next = self.src.get(self.pos+1).copied();
                    next.map_or(false, |n| n != b'/' && n != b'*' && n.is_ascii_alphanumeric())
                }
                b'~' => true, // ~/path
                b'<' => {
                    // <nixpkgs> style path
                    let next = self.src.get(self.pos+1).copied();
                    next.map_or(false, |n| n.is_ascii_alphanumeric() || n == b'_' || n == b'/')
                }
                b'.' => {
                    // ./path
                    let next = self.src.get(self.pos+1).copied();
                    next == Some(b'/') || next == Some(b'.')
                }
                _ if b.is_ascii_digit() => true,
                _ if b.is_ascii_alphabetic() || b == b'_' => {
                    // It's an identifier - is it a keyword or expression?
                    // Look ahead to check
                    let start = self.pos;
                    let mut end = start;
                    let src = self.src;
                    while end < src.len() {
                        let c = src[end];
                        if c.is_ascii_alphanumeric() || c == b'_' || c == b'\'' || c == b'-' {
                            end += 1;
                        } else {
                            break;
                        }
                    }
                    let word = std::str::from_utf8(&src[start..end]).unwrap_or("");
                    // These can start an expression
                    !matches!(word, "then" | "else" | "in" | "rec")
                    // "let", "if", "with", "assert" CAN start expressions
                }
                _ => false,
            }
        }
    }

    fn parse_select(&mut self) -> Expr {
        let mut expr = self.parse_atom();
        loop {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'.') {
                // Could be attribute access or path
                let next = self.src.get(self.pos+1).copied();
                if next.map_or(false, |b| b.is_ascii_alphanumeric() || b == b'_' || b == b'"' || b == b'$') {
                    self.pos += 1;
                    self.skip_whitespace_and_comments();
                    let attr = self.parse_attr_path();
                    self.skip_whitespace_and_comments();
                    let default = if self.starts_with(b"or") {
                        // check it's really "or" keyword
                        let end = self.pos + 2;
                        if end >= self.src.len() || !self.src[end].is_ascii_alphanumeric() {
                            self.pos += 2;
                            Some(Box::new(self.parse_select()))
                        } else {
                            None
                        }
                    } else {
                        None
                    };
                    expr = Expr::Select { expr: Box::new(expr), attr, default };
                } else if next == Some(b'/') || next == Some(b'.') {
                    // It's a path literal that continues
                    break;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        expr
    }

    fn parse_attr_path(&mut self) -> AttrPath {
        let mut path = Vec::new();
        loop {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'"') {
                // String key
                let s = self.parse_simple_string();
                path.push(AttrPathComponent::StringKey(s));
            } else if self.peek() == Some(b'$') && self.src.get(self.pos+1) == Some(&b'{') {
                self.pos += 2;
                let expr = self.parse_expr();
                self.skip_whitespace_and_comments();
                if self.peek() == Some(b'}') { self.pos += 1; }
                path.push(AttrPathComponent::Dynamic(Box::new(expr)));
            } else if let Some(ident) = self.parse_ident() {
                path.push(AttrPathComponent::Ident(ident));
            } else {
                break;
            }

            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'.') {
                let next = self.src.get(self.pos+1).copied();
                if next.map_or(false, |b| b.is_ascii_alphanumeric() || b == b'_' || b == b'"' || b == b'$') {
                    self.pos += 1;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        path
    }

    fn parse_simple_string(&mut self) -> String {
        // Parse "..." string without handling interpolations (for attr keys)
        if self.peek() != Some(b'"') {
            return String::new();
        }
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.src.len() {
            match self.src[self.pos] {
                b'"' => { self.pos += 1; break; }
                b'\\' => {
                    self.pos += 1;
                    if self.pos < self.src.len() {
                        s.push(self.src[self.pos] as char);
                        self.pos += 1;
                    }
                }
                b => { s.push(b as char); self.pos += 1; }
            }
        }
        s
    }

    fn parse_atom(&mut self) -> Expr {
        self.skip_whitespace_and_comments();

        match self.peek() {
            None => Expr::Error,
            Some(b'(') => {
                self.pos += 1;
                let expr = self.parse_expr();
                self.skip_whitespace_and_comments();
                if self.peek() == Some(b')') { self.pos += 1; }
                expr
            }
            Some(b'"') => self.parse_string(),
            Some(b'\'') if self.src.get(self.pos+1) == Some(&b'\'') => self.parse_indented_string(),
            Some(b'[') => self.parse_list(),
            Some(b'{') => self.parse_attr_set(false),
            Some(b'-') => {
                // Negative number
                self.pos += 1;
                if let Some(n) = self.parse_number() {
                    match n {
                        Expr::Int(i) => Expr::Int(-i),
                        Expr::Float(f) => Expr::Float(-f),
                        _ => n,
                    }
                } else {
                    Expr::Error
                }
            }
            Some(b) if b.is_ascii_digit() => {
                self.parse_number().unwrap_or(Expr::Error)
            }
            Some(b'/') | Some(b'.') | Some(b'~') | Some(b'<') => self.parse_path(),
            Some(_) => {
                let ident = match self.parse_ident() {
                    Some(i) => i,
                    None => return Expr::Error,
                };

                match ident.name.as_str() {
                    "true" => Expr::Bool(true),
                    "false" => Expr::Bool(false),
                    "null" => Expr::Null,
                    "rec" => {
                        self.skip_whitespace_and_comments();
                        if self.peek() == Some(b'{') {
                            self.parse_attr_set(true)
                        } else {
                            Expr::Var(ident)
                        }
                    }
                    "let" => self.parse_let(),
                    "if" => self.parse_if(),
                    "with" => self.parse_with(),
                    "assert" => self.parse_assert(),
                    _ => {
                        // Could be a lambda
                        self.skip_whitespace_and_comments();
                        if self.peek() == Some(b':') {
                            self.pos += 1;
                            let body = self.parse_expr();
                            // Check if this identifier has a skip comment
                            // (we handle this at a higher level for lambda parsing)
                            Expr::Lambda {
                                param: LambdaParam::Simple {
                                    name: ident,
                                    skip: false,
                                },
                                body: Box::new(body),
                            }
                        } else {
                            Expr::Var(ident)
                        }
                    }
                }
            }
        }
    }

    fn parse_number(&mut self) -> Option<Expr> {
        let start = self.pos;
        while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.pos < self.src.len() && self.src[self.pos] == b'.' {
            let next = self.src.get(self.pos+1).copied();
            if next.map_or(false, |b| b.is_ascii_digit()) {
                self.pos += 1;
                while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() {
                    self.pos += 1;
                }
                let s = std::str::from_utf8(&self.src[start..self.pos]).unwrap();
                return Some(Expr::Float(s.parse().unwrap_or(0.0)));
            }
        }
        let s = std::str::from_utf8(&self.src[start..self.pos]).unwrap();
        if s.is_empty() {
            None
        } else {
            Some(Expr::Int(s.parse().unwrap_or(0)))
        }
    }

    fn parse_path(&mut self) -> Expr {
        let start = self.pos;

        // Handle ~ prefix  
        if self.peek() == Some(b'~') {
            self.pos += 1;
        }

        // Handle <...> paths
        if self.peek() == Some(b'<') {
            self.pos += 1;
            while self.pos < self.src.len() && self.src[self.pos] != b'>' {
                self.pos += 1;
            }
            if self.pos < self.src.len() { self.pos += 1; }
            return Expr::Path(std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string());
        }

        // Handle regular paths: /foo, ./foo, ../foo
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            if b.is_ascii_alphanumeric() || b == b'/' || b == b'.' || b == b'_' || b == b'-' {
                self.pos += 1;
            } else if b == b'$' && self.src.get(self.pos+1) == Some(&b'{') {
                // path with interpolation
                self.pos += 2;
                let _ = self.parse_expr();
                self.skip_whitespace_and_comments();
                if self.peek() == Some(b'}') { self.pos += 1; }
            } else {
                break;
            }
        }

        Expr::Path(std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string())
    }

    fn parse_string(&mut self) -> Expr {
        // "..." 
        if self.peek() != Some(b'"') {
            return Expr::Error;
        }
        self.pos += 1;
        let mut parts = Vec::new();
        let mut current = String::new();

        while self.pos < self.src.len() {
            match self.src[self.pos] {
                b'"' => {
                    self.pos += 1;
                    break;
                }
                b'\\' => {
                    self.pos += 1;
                    if self.pos < self.src.len() {
                        current.push(self.src[self.pos] as char);
                        self.pos += 1;
                    }
                }
                b'$' if self.src.get(self.pos+1) == Some(&b'{') => {
                    if !current.is_empty() {
                        parts.push(StringPart::Literal(std::mem::take(&mut current)));
                    }
                    self.pos += 2;
                    let expr = self.parse_expr();
                    self.skip_whitespace_and_comments();
                    if self.peek() == Some(b'}') { self.pos += 1; }
                    parts.push(StringPart::Interpolation(Box::new(expr)));
                }
                b => {
                    current.push(b as char);
                    self.pos += 1;
                }
            }
        }
        if !current.is_empty() {
            parts.push(StringPart::Literal(current));
        }
        Expr::Str { parts }
    }

    fn parse_indented_string(&mut self) -> Expr {
        // ''...''
        if !self.starts_with(b"''") {
            return Expr::Error;
        }
        self.pos += 2;
        let mut parts = Vec::new();
        let mut current = String::new();

        while self.pos < self.src.len() {
            if self.starts_with(b"''") {
                // Check if it's ''$ or ''\ (escapes) or '' ending
                let after = self.src.get(self.pos+2).copied();
                if after == Some(b'$') || after == Some(b'\\') || after == Some(b'\'') {
                    // escape sequences
                    current.push(self.src[self.pos+2] as char);
                    self.pos += 3;
                    continue;
                }
                self.pos += 2;
                break;
            }
            match self.src[self.pos] {
                b'$' if self.src.get(self.pos+1) == Some(&b'{') => {
                    if !current.is_empty() {
                        parts.push(StringPart::Literal(std::mem::take(&mut current)));
                    }
                    self.pos += 2;
                    let expr = self.parse_expr();
                    self.skip_whitespace_and_comments();
                    if self.peek() == Some(b'}') { self.pos += 1; }
                    parts.push(StringPart::Interpolation(Box::new(expr)));
                }
                b => {
                    current.push(b as char);
                    self.pos += 1;
                }
            }
        }
        if !current.is_empty() {
            parts.push(StringPart::Literal(current));
        }
        Expr::IndentedStr { parts }
    }

    fn parse_list(&mut self) -> Expr {
        // [ ... ]
        if self.peek() != Some(b'[') {
            return Expr::Error;
        }
        self.pos += 1;
        let mut items = Vec::new();

        loop {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b']') {
                self.pos += 1;
                break;
            }
            if self.peek().is_none() {
                break;
            }
            // In a list, we parse select-level (not full expr to avoid consuming operators)
            let item = self.parse_list_item();
            items.push(item);
        }

        Expr::List(items)
    }

    fn parse_list_item(&mut self) -> Expr {
        // List items are select-level expressions
        self.parse_select()
    }

    pub fn parse_attr_set(&mut self, recursive: bool) -> Expr {
        if self.peek() != Some(b'{') {
            return Expr::Error;
        }
        self.pos += 1;
        let mut entries = Vec::new();

        loop {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'}') {
                self.pos += 1;
                break;
            }
            if self.peek().is_none() {
                break;
            }

            // Check for inherit
            let saved_pos = self.pos;
            if let Some(ident) = self.parse_ident() {
                if ident.name == "inherit" {
                    self.skip_whitespace_and_comments();
                    let from = if self.peek() == Some(b'(') {
                        self.pos += 1;
                        let e = self.parse_expr();
                        self.skip_whitespace_and_comments();
                        if self.peek() == Some(b')') { self.pos += 1; }
                        Some(e)
                    } else {
                        None
                    };

                    let mut names = Vec::new();
                    loop {
                        self.skip_whitespace_and_comments();
                        if self.peek() == Some(b';') || self.peek() == Some(b'}') || self.peek().is_none() {
                            break;
                        }
                        if let Some(n) = self.parse_ident() {
                            names.push(n);
                        } else {
                            break;
                        }
                    }

                    self.skip_whitespace_and_comments();
                    if self.peek() == Some(b';') { self.pos += 1; }

                    // Attr set inherits are not tracked for dead code
                    // We still need to parse them for variable references
                    for name in &names {
                        if let Some(f) = &from {
                            let path = vec![AttrPathComponent::Ident(name.clone())];
                            entries.push(AttrEntry {
                                path,
                                value: Box::new(Expr::Select {
                                    expr: Box::new(f.clone()),
                                    attr: vec![AttrPathComponent::Ident(name.clone())],
                                    default: None,
                                }),
                            });
                        } else {
                            let path = vec![AttrPathComponent::Ident(name.clone())];
                            entries.push(AttrEntry {
                                path,
                                value: Box::new(Expr::Var(name.clone())),
                            });
                        }
                    }
                    continue;
                } else {
                    self.pos = saved_pos;
                }
            }

            // Parse attr path = expr ;
            let path = self.parse_attr_path();
            if path.is_empty() {
                // Skip unknown token
                self.pos += 1;
                continue;
            }

            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'=') {
                self.pos += 1;
                let value = self.parse_expr();
                self.skip_whitespace_and_comments();
                if self.peek() == Some(b';') { self.pos += 1; }
                entries.push(AttrEntry { path, value: Box::new(value) });
            } else {
                break;
            }
        }

        Expr::AttrSet { recursive, entries }
    }

    pub fn parse_let(&mut self) -> Expr {
        // "let" already consumed if called from parse_atom
        // Actually we call this after parsing "let" ident
        let mut bindings = Vec::new();

        loop {
            // Save position to check for skip comment
            let before_ws_pos = self.pos;
            self.skip_whitespace_and_comments();
            let after_ws_pos = self.pos;

            if self.peek().is_none() {
                break;
            }

            // Check for "in" keyword
            let saved = self.pos;
            if let Some(ident) = self.parse_ident() {
                if ident.name == "in" {
                    break;
                }

                if ident.name == "inherit" {
                    // inherit binding
                    // Check skip comment
                    let skip = self.check_deadnix_skip(before_ws_pos, after_ws_pos);

                    self.skip_whitespace_and_comments();
                    let from = if self.peek() == Some(b'(') {
                        self.pos += 1;
                        let e = self.parse_expr();
                        self.skip_whitespace_and_comments();
                        if self.peek() == Some(b')') { self.pos += 1; }
                        Some(Box::new(e))
                    } else {
                        None
                    };

                    let mut names = Vec::new();
                    loop {
                        self.skip_whitespace_and_comments();
                        if self.peek() == Some(b';') || self.peek() == Some(b'}') || self.peek().is_none() {
                            break;
                        }
                        // Check if "in"
                        let s = self.pos;
                        if let Some(i) = self.parse_ident() {
                            if i.name == "in" {
                                self.pos = s; // put it back
                                break;
                            }
                            names.push(i);
                        } else {
                            break;
                        }
                    }

                    self.skip_whitespace_and_comments();
                    if self.peek() == Some(b';') { self.pos += 1; }

                    bindings.push(LetBinding::Inherit { from, names, skip });
                    continue;
                }

                self.pos = saved;
            }

            // Parse name = expr ;
            let skip = self.check_deadnix_skip(before_ws_pos, after_ws_pos);

            // Parse the binding name
            if let Some(name) = self.parse_ident() {
                self.skip_whitespace_and_comments();
                if self.peek() == Some(b'=') {
                    self.pos += 1;
                    let value = self.parse_expr();
                    self.skip_whitespace_and_comments();
                    if self.peek() == Some(b';') { self.pos += 1; }
                    bindings.push(LetBinding::Plain { name, value: Box::new(value), skip });
                } else {
                    // error
                    break;
                }
            } else {
                break;
            }
        }

        self.skip_whitespace_and_comments();
        let body = self.parse_expr();

        Expr::Let { bindings, body: Box::new(body) }
    }

    fn check_deadnix_skip(&self, before_ws_pos: usize, after_ws_pos: usize) -> bool {
        // Scan the whitespace/comment region from before_ws_pos to after_ws_pos
        // Check if there's a "# deadnix: skip" that is the LAST comment before after_ws_pos
        let region = &self.src[before_ws_pos..after_ws_pos];
        let region_str = std::str::from_utf8(region).unwrap_or("");

        // Find the last comment in this region
        let mut last_comment_is_skip = false;
        let mut i = 0;
        let bytes = region.as_ref();

        while i < bytes.len() {
            if bytes[i] == b'#' {
                let start = i;
                while i < bytes.len() && bytes[i] != b'\n' {
                    i += 1;
                }
                let comment = std::str::from_utf8(&bytes[start..i]).unwrap_or("");
                last_comment_is_skip = comment.contains("deadnix: skip");
            } else {
                last_comment_is_skip = false;
                i += 1;
            }
        }

        let _ = region_str; // suppress warning
        last_comment_is_skip
    }

    fn parse_if(&mut self) -> Expr {
        self.skip_whitespace_and_comments();
        let cond = self.parse_expr();
        self.skip_whitespace_and_comments();
        // expect "then"
        let _then_kw = self.parse_ident();
        let then = self.parse_expr();
        self.skip_whitespace_and_comments();
        // expect "else"
        let _else_kw = self.parse_ident();
        let else_ = self.parse_expr();
        Expr::If {
            cond: Box::new(cond),
            then: Box::new(then),
            else_: Box::new(else_),
        }
    }

    fn parse_with(&mut self) -> Expr {
        self.skip_whitespace_and_comments();
        let namespace = self.parse_expr();
        self.skip_whitespace_and_comments();
        if self.peek() == Some(b';') { self.pos += 1; }
        let body = self.parse_expr();
        Expr::With {
            namespace: Box::new(namespace),
            body: Box::new(body),
        }
    }

    fn parse_assert(&mut self) -> Expr {
        self.skip_whitespace_and_comments();
        let cond = self.parse_expr();
        self.skip_whitespace_and_comments();
        if self.peek() == Some(b';') { self.pos += 1; }
        let body = self.parse_expr();
        Expr::Assert {
            cond: Box::new(cond),
            body: Box::new(body),
        }
    }

    /// Parse a lambda: handles { ... }: body and identifier: body cases
    /// This is called from parse_atom when we identify a potential lambda
    pub fn try_parse_lambda_pattern(&mut self) -> Option<Expr> {
        let start = self.pos;

        // Try to parse pattern lambda: { a, b, ... }: body
        // or @-pattern: args@{ a, b }: body

        self.skip_whitespace_and_comments();

        // Check for identifier@{ pattern
        let saved = self.pos;
        let at_name = if let Some(ident) = self.parse_ident() {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'@') {
                self.pos += 1;
                self.skip_whitespace_and_comments();
                Some(ident)
            } else {
                self.pos = saved;
                None
            }
        } else {
            None
        };

        if self.peek() != Some(b'{') {
            self.pos = start;
            return None;
        }

        self.pos += 1; // consume {
        let mut params = Vec::new();
        let mut ellipsis = false;

        loop {
            self.skip_whitespace_and_comments();
            if self.peek() == Some(b'}') {
                self.pos += 1;
                break;
            }
            if self.starts_with(b"...") {
                self.pos += 3;
                ellipsis = true;
                self.skip_whitespace_and_comments();
                if self.peek() == Some(b'}') { self.pos += 1; }
                break;
            }

            // Parse identifier with optional default
            if let Some(name) = self.parse_ident() {
                self.skip_whitespace_and_comments();
                let default = if self.peek() == Some(b'?') {
                    self.pos += 1;
                    Some(Box::new(self.parse_apply()))
                } else {
                    None
                };

                params.push(PatternEntry { name, default, skip: false });

                self.skip_whitespace_and_comments();
                if self.peek() == Some(b',') {
                    self.pos += 1;
                }
            } else {
                self.pos = start;
                return None;
            }
        }

        self.skip_whitespace_and_comments();

        // Check for @name after pattern
        let at_name_after = if self.peek() == Some(b'@') {
            self.pos += 1;
            self.skip_whitespace_and_comments();
            self.parse_ident()
        } else {
            None
        };

        let final_at_name = at_name.or(at_name_after);

        self.skip_whitespace_and_comments();
        if self.peek() != Some(b':') {
            self.pos = start;
            return None;
        }
        self.pos += 1;

        let body = self.parse_expr();

        Some(Expr::Lambda {
            param: LambdaParam::Pattern {
                at_name: final_at_name,
                at_skip: false,
                params,
                ellipsis,
            },
            body: Box::new(body),
        })
    }
}

/// Parse a full Nix expression from source
pub fn parse(src: &str) -> Expr {
    let mut parser = NixParser::new(src);
    parser.parse_top_level()
}

pub struct NixParser {
    src: String,
    pos: usize,
}

impl NixParser {
    pub fn new(src: &str) -> Self {
        NixParser {
            src: src.to_string(),
            pos: 0,
        }
    }

    pub fn parse_top_level(&mut self) -> Expr {
        let mut p = Parser::new(&self.src);

        // The top-level of a Nix file can be:
        // 1. A lambda: { args }: expr or ident: expr
        // 2. A let expression: let ... in expr
        // 3. Any other expression

        // But we need to handle comment-based skip pragmas
        // Try to parse as lambda pattern first
        p.skip_whitespace_and_comments();
        let saved = p.pos;

        // Try pattern lambda
        if let Some(expr) = p.try_parse_lambda_pattern() {
            // Check if there's more - we might have parsed only part
            p.skip_whitespace_and_comments();
            if p.pos >= self.src.len() || !p.can_start_atom() {
                return expr;
            }
        }

        p.pos = saved;
        p.parse_expr()
    }
}
