        }
        Expr::Str { parts } | Expr::IndentedStr { parts } => {
            for part in parts {
                if let StringPart::Interpolation(e) = part {
                    collect_used_in_expr(e, used);
                }
            }
        }
        _ => {}
    }
}

fn collect_used_names(expr: &Expr) -> HashSet<String> {
    let mut used = HashSet::new();
    collect_used_in_expr(expr, &mut used);
    used
}

/// Edit the file to remove unused code
pub fn edit_file(content: &str, diagnostics: &[Diagnostic]) -> String {
    // This is complex - we need to modify the AST and regenerate the source
    // For now, implement a simple text-based approach

    let lines = build_line_index(content);
    let expr = parse(content);

    // We need to rebuild the source with the unused bindings removed
    // For lambda args: rename to _name
    // For pattern entries: remove from pattern
    // For let bindings: remove the binding
    // For inherit: remove the specific name

    apply_edits(content, diagnostics, &lines, &expr)
}

fn apply_edits(content: &str, diagnostics: &[Diagnostic], line_starts: &[usize], expr: &Expr) -> String {
    // Collect edit operations
    let mut edits: Vec<Edit> = Vec::new();

    collect_edits_for_expr(content, expr, diagnostics, line_starts, &mut edits);

    // Sort edits in reverse order (so we can apply from end to start)
    edits.sort_by(|a, b| b.start.cmp(&a.start));

    // Deduplicate
    edits.dedup_by(|a, b| a.start == b.start && a.end == b.end);

    // Apply edits
    let bytes = content.as_bytes();
    let mut result = content.to_string();

    for edit in &edits {
        let start = edit.start;
        let end = edit.end;

        if start > result.len() || end > result.len() {
            continue;
        }

        result = format!("{}{}{}", &result[..start], &edit.replacement, &result[end..]);
    }

    result
}

#[derive(Debug)]
struct Edit {
    start: usize,
    end: usize,
    replacement: String,
}

fn is_diag_at(diags: &[Diagnostic], span: &Span, line_starts: &[usize]) -> bool {
    let (line, col) = offset_to_line_col(span.start, line_starts);
    let (_, end_col) = offset_to_line_col(span.end, line_starts);
    diags.iter().any(|d| d.line == line && d.column == col && d.end_column == end_col)
}

fn collect_edits_for_expr(
    content: &str,
    expr: &Expr,
    diags: &[Diagnostic],
    line_starts: &[usize],
    edits: &mut Vec<Edit>,
) {
    match expr {
        Expr::Lambda { param, body } => {
            match param {
                LambdaParam::Simple { name, .. } => {
                    if is_diag_at(diags, &name.span, line_starts) {
                        // Rename to _name
                        let new_name = format!("_{}", name.name);
                        edits.push(Edit {
                            start: name.span.start,
                            end: name.span.end,
                            replacement: new_name,
                        });
                    }
                }
                LambdaParam::Pattern { at_name, params, ellipsis, .. } => {
                    // Find which params are unused
                    let mut unused_params: Vec<usize> = Vec::new();
                    for (i, entry) in params.iter().enumerate() {
                        if is_diag_at(diags, &entry.name.span, line_starts) {
                            unused_params.push(i);
                        }
                    }

                    // Check if @ name is unused
                    let at_unused = at_name.as_ref().map_or(false, |at| {
                        is_diag_at(diags, &at.span, line_starts)
                    });

                    if !unused_params.is_empty() || at_unused {
                        // Need to rewrite the pattern
                        let new_params: Vec<&PatternEntry> = params.iter().enumerate()
                            .filter(|(i, _)| !unused_params.contains(i))
                            .map(|(_, p)| p)
                            .collect();

                        // Find the span of the whole pattern (including @ part)
                        let pattern_start = if let Some(at) = at_name {
                            if at.span.start < params.first().map_or(usize::MAX, |p| p.name.span.start) {
                                at.span.start
                            } else {
                                find_pattern_brace_start(content, params)
                            }
                        } else {
                            find_pattern_brace_start(content, params)
                        };

                        let pattern_end = find_pattern_end(content, pattern_start);

                        if pattern_start < pattern_end {
                            // Build new pattern text
                            let new_pattern = build_new_pattern(&new_params, *ellipsis, 
                                if at_unused { None } else { at_name.as_ref() },
                                content, at_name.as_ref(), params);

                            edits.push(Edit {
                                start: pattern_start,
                                end: pattern_end,
                                replacement: new_pattern,
                            });
                        }
                    }
                }
            }
            collect_edits_for_expr(content, body, diags, line_starts, edits);
            if let LambdaParam::Pattern { params, .. } = param {
                for p in params {
                    if let Some(d) = &p.default {
                        collect_edits_for_expr(content, d, diags, line_starts, edits);
                    }
                }
            }
        }
        Expr::Let { bindings, body } => {
            // Find unused bindings
            for binding in bindings {
                match binding {
                    LetBinding::Plain { name, value, .. } => {
                        if is_diag_at(diags, &name.span, line_starts) {
                            // Remove this binding (name = value ;)
                            let span = find_let_binding_span(content, &name.span);
                            edits.push(Edit {
                                start: span.0,
                                end: span.1,
                                replacement: String::new(),
                            });
                        } else {
                            collect_edits_for_expr(content, value, diags, line_starts, edits);
                        }
                    }
                    LetBinding::Inherit { names, from, .. } => {
                        // Find which names are unused
                        let unused: Vec<&Ident> = names.iter()
                            .filter(|n| is_diag_at(diags, &n.span, line_starts))
                            .collect();

                        if unused.len() == names.len() {
                            // Remove entire inherit statement
                            let span = find_inherit_span(content, names);
                            edits.push(Edit {
                                start: span.0,
                                end: span.1,
                                replacement: String::new(),
                            });
                        } else if !unused.is_empty() {
                            // Remove specific names from inherit
                            for name in &unused {
                                let span = find_inherit_name_span(content, name, names, from.as_ref().map(|e| e.as_ref()));
                                edits.push(Edit {
                                    start: span.0,
                                    end: span.1,
                                    replacement: String::new(),
                                });
                            }
                        }

                        if let Some(e) = from {
                            collect_edits_for_expr(content, e, diags, line_starts, edits);
                        }
                    }
                }
            }
            collect_edits_for_expr(content, body, diags, line_starts, edits);
        }
        Expr::Apply { func, arg } => {
            collect_edits_for_expr(content, func, diags, line_starts, edits);
            collect_edits_for_expr(content, arg, diags, line_starts, edits);
        }
        Expr::Select { expr, default, .. } => {
            collect_edits_for_expr(content, expr, diags, line_starts, edits);
            if let Some(d) = default {
                collect_edits_for_expr(content, d, diags, line_starts, edits);
            }
        }
        Expr::If { cond, then, else_ } => {
            collect_edits_for_expr(content, cond, diags, line_starts, edits);
            collect_edits_for_expr(content, then, diags, line_starts, edits);
            collect_edits_for_expr(content, else_, diags, line_starts, edits);
        }
        Expr::With { namespace, body } => {
            collect_edits_for_expr(content, namespace, diags, line_starts, edits);
            collect_edits_for_expr(content, body, diags, line_starts, edits);
        }
        Expr::Assert { cond, body } => {
            collect_edits_for_expr(content, cond, diags, line_starts, edits);
            collect_edits_for_expr(content, body, diags, line_starts, edits);
        }
        Expr::BinOp { left, right, .. } => {
            collect_edits_for_expr(content, left, diags, line_starts, edits);
            collect_edits_for_expr(content, right, diags, line_starts, edits);
        }
        Expr::UnaryOp { expr, .. } => {
            collect_edits_for_expr(content, expr, diags, line_starts, edits);
        }
        Expr::HasAttr { expr, .. } => {
            collect_edits_for_expr(content, expr, diags, line_starts, edits);
        }
        Expr::List(items) => {
            for item in items {
                collect_edits_for_expr(content, item, diags, line_starts, edits);
            }
        }
        Expr::AttrSet { entries, .. } => {
            for entry in entries {
                collect_edits_for_expr(content, &entry.value, diags, line_starts, edits);
            }
        }
        Expr::Str { parts } | Expr::IndentedStr { parts } => {
            for part in parts {
                if let StringPart::Interpolation(e) = part {
                    collect_edits_for_expr(content, e, diags, line_starts, edits);
                }
            }
        }
        _ => {}
    }
}

fn find_pattern_brace_start(content: &str, params: &[PatternEntry]) -> usize {
    let bytes = content.as_bytes();
    let first_param_start = params.first().map_or(0, |p| p.name.span.start);

    // Search backwards for '{'
    let mut pos = first_param_start;
    while pos > 0 {
        pos -= 1;
        if bytes[pos] == b'{' {
            return pos;
        }
    }
    0
}

fn find_pattern_end(content: &str, start: usize) -> usize {
    let bytes = content.as_bytes();
    let mut pos = start;

    // Skip @ prefix if present
    if pos < bytes.len() && bytes[pos] != b'{' {
        // find the @
        while pos < bytes.len() && bytes[pos] != b'@' {
            pos += 1;
        }
        if pos < bytes.len() { pos += 1; }
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') {
            pos += 1;
        }
    }

    // Now find the closing }
    let mut depth = 0;
    while pos < bytes.len() {
        match bytes[pos] {
            b'{' => { depth += 1; pos += 1; }
            b'}' => {
                depth -= 1;
                pos += 1;
                if depth == 0 { break; }
            }
            _ => { pos += 1; }
        }
    }
    pos
}

fn build_new_pattern(
    new_params: &[&PatternEntry],
    ellipsis: bool,
    at_name: Option<&Ident>,
    content: &str,
    orig_at: Option<&Ident>,
    all_params: &[PatternEntry],
) -> String {
    let mut result = String::new();

    if let Some(at) = at_name {
        result.push_str(&at.name);
        result.push('@');
    }

    result.push_str("{ ");

    let mut parts: Vec<String> = Vec::new();

    for param in new_params {
        let mut s = param.name.name.clone();
        if let Some(default) = &param.default {
            // Extract the default value text from content
            // We need to find the ? and the expression
            let after_name = param.name.span.end;
            let bytes = content.as_bytes();
            let mut pos = after_name;
            // Skip whitespace
            while pos < bytes.len() && bytes[pos].is_ascii_whitespace() { pos += 1; }
            if pos < bytes.len() && bytes[pos] == b'?' {
                pos += 1;
                let default_start = pos;
                // Find the end of the default: either , or } 
                let mut depth = 0;
                while pos < bytes.len() {
                    match bytes[pos] {
                        b'(' | b'[' | b'{' => { depth += 1; pos += 1; }
                        b')' | b']' | b'}' => {
                            if depth == 0 { break; }
                            depth -= 1; pos += 1;
                        }
                        b',' if depth == 0 => break,
                        _ => { pos += 1; }
                    }
                }
                let default_text = &content[default_start..pos];
                s.push_str(" ?");
                s.push_str(default_text);
            } else {
                // fallback
                let _ = default;
            }
        }
        parts.push(s);
    }

    if ellipsis {
        parts.push("...".to_string());
    }

    result.push_str(&parts.join(", "));
    result.push_str(" }");

    result
}

fn find_let_binding_span(content: &str, name_span: &Span) -> (usize, usize) {
    let bytes = content.as_bytes();

    // Find the start: go backwards to find the newline + whitespace
    let mut start = name_span.start;

    // Check for # deadnix: skip comment above
    // Go backwards from name to find previous line end
    let mut line_start = start;
    while line_start > 0 && bytes[line_start-1] != b'\n' {
        line_start -= 1;
    }

    // Check if there's a deadnix: skip on the previous line
    let prev_line_end = line_start.saturating_sub(1); // the \n before current line
    if prev_line_end > 0 {
        let mut prev_line_start = prev_line_end.saturating_sub(1);
        while prev_line_start > 0 && bytes[prev_line_start-1] != b'\n' {
            prev_line_start -= 1;
        }
        let prev_line = &content[prev_line_start..prev_line_end];
        if prev_line.contains("deadnix: skip") {
            // Include the skip comment line too
            start = prev_line_start;
        } else {
            start = line_start;
        }
    } else {
        start = line_start;
    }

    // Find the end: go forward past ; to end of line
    let mut end = name_span.start;
    // Skip past the name, =, value, ;
    while end < bytes.len() && bytes[end] != b';' {
        end += 1;
    }
    if end < bytes.len() { end += 1; } // include ;

    // Include trailing newline if the next non-whitespace is on the next line
    if end < bytes.len() && bytes[end] == b'\n' {
        end += 1;
    }

    (start, end)
}

fn find_inherit_span(content: &str, names: &[Ident]) -> (usize, usize) {
    let bytes = content.as_bytes();

    // Find "inherit" keyword before the first name
    let first = names.first().map_or(0, |n| n.span.start);

    // Search backwards for "inherit"
    let mut start = first;
    // Go to start of line
    while start > 0 && bytes[start-1] != b'\n' {
        start -= 1;
    }

    // Check for deadnix:skip on previous line
    let line_start = start;
    let prev_line_end = line_start.saturating_sub(1);
    if prev_line_end > 0 {
        let mut prev_line_start = prev_line_end.saturating_sub(1);
        while prev_line_start > 0 && bytes[prev_line_start-1] != b'\n' {
            prev_line_start -= 1;
        }
        let prev_line = &content[prev_line_start..prev_line_end];
        if prev_line.contains("deadnix: skip") {
            start = prev_line_start;
        }
    }

    // Find the end: past the last name and ;
    let last = names.last().map_or(0, |n| n.span.end);
    let mut end = last;
    while end < bytes.len() && bytes[end] != b';' {
        end += 1;
    }
    if end < bytes.len() { end += 1; }
    if end < bytes.len() && bytes[end] == b'\n' { end += 1; }

    (start, end)
}

fn find_inherit_name_span(
    content: &str, 
    name: &Ident, 
    all_names: &[Ident],
    _from: Option<&Expr>,
) -> (usize, usize) {
    let bytes = content.as_bytes();
    let name_start = name.span.start;
    let name_end = name.span.end;

    // Find the name's position relative to others
    let pos_in_list = all_names.iter().position(|n| n.span.start == name_start);

    // We need to remove the name and its surrounding whitespace/comma
    let start;
    let end;

    if let Some(idx) = pos_in_list {
        if idx + 1 < all_names.len() {
            // Not the last - remove name + following whitespace up to next name
            start = name_start;
            let next_start = all_names[idx + 1].span.start;
            end = next_start;
        } else if idx > 0 {
            // Last item - remove preceding whitespace + name
            let prev_end = all_names[idx - 1].span.end;
            start = prev_end;
            end = name_end;
        } else {
            start = name_start;
            end = name_end;
        }
    } else {
        start = name_start;
        end = name_end;
    }

    (start, end)
}
