use std::path::Path;
use crate::analysis::{Diagnostic, DiagKind};

pub fn print_json(diagnostics: &[Diagnostic], file_path: &Path) {
    let file_str = file_path.display().to_string();

    print!("{{\"file\":{},\"results\":[", json_string(&file_str));

    for (i, diag) in diagnostics.iter().enumerate() {
        if i > 0 { print!(","); }
        print!("{{\"column\":{},\"endColumn\":{},\"line\":{},\"message\":{}}}",
            diag.column,
            diag.end_column,
            diag.line,
            json_string(&diag.message),
        );
    }

    println!("]}}");
}

fn json_string(s: &str) -> String {
    let mut result = String::from('"');
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result.push('"');
    result
}

pub fn print_human_readable(
    diagnostics: &[Diagnostic],
    file_path: &Path,
    content: &str,
    no_color: bool,
) {
    if diagnostics.is_empty() {
        return;
    }

    let file_str = file_path.display().to_string();
    let lines: Vec<&str> = content.lines().collect();

    // Find max line number (to determine gutter width)
    let max_line = diagnostics.iter().map(|d| d.line).max().unwrap_or(1);
    let num_width = digits(max_line);
    let gutter_width = num_width + 2; // " N " where N is right-aligned

    // Print warning header
    if no_color {
        println!("Warning: Unused declarations were found.");
    } else {
        println!("\x1b[33mWarning:\x1b[0m Unused declarations were found.");
    }

    // Print file anchor (╭─[file:line:col])
    let first = &diagnostics[0];

    if no_color {
        println!("{:>gutter_width$}╭─[{}:{}:{}]", 
            "", file_str, first.line, first.column,
            gutter_width = gutter_width);
    } else {
        print!("{}", " ".repeat(gutter_width));
        print!("\x1b[38;5;246m╭\x1b[0m");
        print!("\x1b[38;5;246m─\x1b[0m");
        print!("\x1b[38;5;246m[\x1b[0m");
        print!("{}", file_str);
        print!(":{}", first.line);
        print!(":{}", first.column);
        println!("\x1b[38;5;246m]\x1b[0m");
    }

    // Group diagnostics by line
    let mut by_line: Vec<(usize, Vec<&Diagnostic>)> = Vec::new();
    for diag in diagnostics {
        if let Some(entry) = by_line.iter_mut().find(|(l, _)| *l == diag.line) {
            entry.1.push(diag);
        } else {
            by_line.push((diag.line, vec![diag]));
        }
    }

    // Print each line's diagnostics
    for (line_num, line_diags) in &by_line {
        let source_line = lines.get(line_num - 1).copied().unwrap_or("");

        // Determine max endColumn for message placement
        let max_end_col = line_diags.iter().map(|d| d.end_column).max().unwrap_or(0);

        // Print source line with highlighting
        print_source_line(source_line, line_diags, *line_num, num_width, gutter_width, no_color);

        // Print indicator lines
        // Sort by column descending (rightmost first = shown closest to source)
        let mut sorted_diags: Vec<&Diagnostic> = line_diags.iter().copied().collect();
        sorted_diags.sort_by(|a, b| b.column.cmp(&a.column));

        // For each diagnostic (rightmost first), print a row
        for (idx, diag) in sorted_diags.iter().enumerate() {
            // Print the continuation row
            print_indicator_row(
                diag,
                &sorted_diags[idx+1..],  // remaining (leftward) diags that need connectors
                max_end_col,
                num_width,
                gutter_width,
                no_color,
            );
        }
    }
}

fn print_source_line(
    source: &str,
    diags: &[&Diagnostic],
    line_num: usize,
    num_width: usize,
    gutter_width: usize,
    no_color: bool,
) {
    if no_color {
        println!("{:>width$} │{}", line_num, source, width = num_width + 1);
        return;
    }

    // Build a set of highlighted spans
    // Each character in the source gets a color
    let source_chars: Vec<char> = source.chars().collect();

    // Print line number + border
    print!("\x1b[38;5;246m{:>width$} │\x1b[0m", line_num, width = num_width + 1);

    // Print source with highlighting
    for (i, ch) in source_chars.iter().enumerate() {
        let col = i + 1; // 1-indexed

        // Find if this char is in any highlighted span
        let color = diags.iter().find_map(|d| {
            if col >= d.column && col < d.end_column {
                Some(diag_color(&d.kind))
            } else {
                None
            }
        });

        if let Some(c) = color {
            print!("\x1b[{}m{}\x1b[0m", c, ch);
        } else {
            print!("\x1b[38;5;249m{}\x1b[0m", ch);
        }
    }
    println!();
}

fn print_indicator_row(
    current: &Diagnostic,
    remaining: &[&Diagnostic], // diagnostics to the left (need connector lines)
    max_end_col: usize,
    num_width: usize,
    gutter_width: usize,
    no_color: bool,
) {
    // source_start is the position in output after the gutter+bar
    let source_start = gutter_width + 1; // gutter + '│'

    // Position of the current indicator (0-indexed from source start)
    let length = current.end_column - current.column;
    let half = length / 2;
    let indicator_pos = (current.column - 1) + half; // 0-indexed from source start

    // Position of the message (0-indexed from source start)
    let message_pos = max_end_col; // = max_end_col - 1 + 1 = max_end_col

    let color = diag_color(&current.kind);

    if no_color {
        // Build the indicator line
        let mut line = String::new();

        // Add gutter spaces + bar
        line.push_str(&" ".repeat(gutter_width));
        line.push('│');

        // Build indicator area character by character
        let total_width = message_pos + 1;
        let mut chars: Vec<char> = vec![' '; total_width];

        // Place │ connectors for remaining (leftward) items
        for rem in remaining {
            let rem_len = rem.end_column - rem.column;
            let rem_half = rem_len / 2;
            let rem_pos = (rem.column - 1) + rem_half;
            if rem_pos < total_width {
                chars[rem_pos] = '│';
            }
        }

        // Place ╰ and dashes
        if indicator_pos < total_width {
            chars[indicator_pos] = '╰';
        }
        let dash_count = if message_pos > indicator_pos { message_pos - indicator_pos - 1 } else { 0 };
        for j in 1..=dash_count {
            if indicator_pos + j < total_width {
                chars[indicator_pos + j] = '─';
            }
        }

        let indicator_str: String = chars.into_iter().collect();
        line.push_str(&indicator_str);

        println!("{} {}", line, current.message);
    } else {
        // Colored version
        // Print gutter
        print!("\x1b[38;5;240m{:>width$} │\x1b[0m", "", width = num_width + 1);

        // Build the indicator area
        let total_width = message_pos;
        let mut pos = 0;

        // Collect remaining positions
        let mut remaining_positions: Vec<(usize, &str)> = remaining.iter().map(|rem| {
            let rem_len = rem.end_column - rem.column;
            let rem_half = rem_len / 2;
            let rem_pos = (rem.column - 1) + rem_half;
            (rem_pos, diag_color(&rem.kind))
        }).collect();
        remaining_positions.sort_by_key(|(p, _)| *p);

        while pos < total_width {
            // Check if this is a connector position
            if let Some(idx) = remaining_positions.iter().position(|(p, _)| *p == pos) {
                let c = remaining_positions[idx].1;
                print!("\x1b[{}m│\x1b[0m", c);
                pos += 1;
            } else if pos == indicator_pos {
                print!("\x1b[{}m╰\x1b[0m", color);
                pos += 1;
                // Print dashes
                while pos < total_width {
                    // Check connector positions
                    if remaining_positions.iter().any(|(p, _)| *p == pos) {
                        break;
                    }
                    print!("\x1b[{}m─\x1b[0m", color);
                    pos += 1;
                }
            } else {
                print!(" ");
                pos += 1;
            }
        }

        println!(" {}", current.message);
    }
}

fn diag_color(kind: &DiagKind) -> &'static str {
    match kind {
        DiagKind::UnusedLambdaArg => "36",    // cyan
        DiagKind::UnusedLambdaPattern => "35", // magenta
        DiagKind::UnusedLetBinding => "31",    // red
        DiagKind::UsedUnderscore => "36",      // cyan (same as lambda arg)
    }
}

fn digits(n: usize) -> usize {
    if n == 0 { return 1; }
    let mut d = 0;
    let mut n = n;
    while n > 0 {
        d += 1;
        n /= 10;
    }
    d
}
