                self.pos += 2;
                self.skip_ws();
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Gte, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'<') && self.peek_at(1) != Some(b'=') && self.peek_at(1) != Some(b'<') {
