                // Simple heuristic: if followed by identifier-char, it might be comparison
                self.pos += 1;
                self.skip_ws();
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Lt, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'>') && self.peek_at(1) != Some(b'=') {
                self.pos += 1;
                self.skip_ws();
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Gt, left: Box::new(left), right: Box::new(right) };
