// Nix parser
// Handles full Nix expression syntax

#[derive(Debug, Clone)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Self {
        Span { start, end }
    }
}

#[derive(Debug, Clone)]
pub struct Ident {
    pub name: String,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum LetBinding {
    Plain {
        name: Ident,
        value: Box<Expr>,
        skip: bool,
    },
    Inherit {
        from: Option<Box<Expr>>,
        names: Vec<Ident>,
        skip: bool,
    },
}

#[derive(Debug, Clone)]
pub enum LambdaParam {
    Simple {
        name: Ident,
        skip: bool,
    },
    Pattern {
        at_name: Option<Ident>,
        at_skip: bool,
        params: Vec<PatternEntry>,
        ellipsis: bool,
    },
}

#[derive(Debug, Clone)]
pub struct PatternEntry {
    pub name: Ident,
    pub default: Option<Box<Expr>>,
    pub skip: bool,
}

#[derive(Debug, Clone)]
