pub struct Parser {
    src: Vec<u8>,
    pos: usize,
}

impl Parser {
    pub fn new(src: &str) -> Self {
        Parser {
            src: src.as_bytes().to_vec(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<u8> {
        self.src.get(self.pos + offset).copied()
    }

    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.src.len() {
                let b = self.src[self.pos];
                if b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' {
                    self.pos += 1;
                } else {
                    break;
                }
            }

            if self.pos + 1 < self.src.len() && self.src[self.pos] == b'#' {
                while self.pos < self.src.len() && self.src[self.pos] != b'\n' {
                    self.pos += 1;
                }
                continue;
            }

            if self.pos + 1 < self.src.len() && self.src[self.pos] == b'/' && self.src[self.pos+1] == b'*' {
                self.pos += 2;
                while self.pos + 1 < self.src.len() {
                    if self.src[self.pos] == b'*' && self.src[self.pos+1] == b'/' {
                        self.pos += 2;
                        break;
                    }
                    self.pos += 1;
                }
                continue;
            }

            break;
        }
    }

    /// Check for deadnix:skip between pos `from` and `to`
    fn has_deadnix_skip(&self, from: usize, to: usize) -> bool {
        let region = &self.src[from..to.min(self.src.len())];
        let mut i = 0;
        let mut last_comment_is_skip = false;

        while i < region.len() {
            if region[i] == b'#' {
                let start = i;
                while i < region.len() && region[i] != b'\n' {
                    i += 1;
                }
                let comment = std::str::from_utf8(&region[start..i]).unwrap_or("");
                last_comment_is_skip = comment.contains("deadnix: skip");
            } else if region[i] == b'/' && i + 1 < region.len() && region[i+1] == b'*' {
                last_comment_is_skip = false;
                i += 2;
                while i + 1 < region.len() {
                    if region[i] == b'*' && region[i+1] == b'/' {
                        i += 2;
                        break;
                    }
                    i += 1;
                }
            } else {
                if region[i] != b' ' && region[i] != b'\t' && region[i] != b'\n' && region[i] != b'\r' {
                    // Non-whitespace non-comment character - reset
                    last_comment_is_skip = false;
                }
                i += 1;
            }
        }

        last_comment_is_skip
    }

    fn parse_ident_raw(&mut self) -> Option<String> {
        if self.pos >= self.src.len() { return None; }
        let first = self.src[self.pos];
        if !(first.is_ascii_alphabetic() || first == b'_') { return None; }
        let start = self.pos;
        self.pos += 1;
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            if b.is_ascii_alphanumeric() || b == b'_' || b == b'\'' || b == b'-' {
                self.pos += 1;
            } else {
                break;
            }
        }
        Some(std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string())
    }

    fn parse_ident(&mut self) -> Option<Ident> {
        let start = self.pos;
        let name = self.parse_ident_raw()?;
        Some(Ident { name, span: Span::new(start, self.pos) })
    }

    fn starts_with(&self, s: &[u8]) -> bool {
        self.src[self.pos..].starts_with(s)
    }

    /// Main entry point
    pub fn parse_expr(&mut self) -> Expr {
        self.skip_ws();
        let expr = self.parse_expr_inner();
        expr
    }

    fn parse_expr_inner(&mut self) -> Expr {
        self.skip_ws();

        // Check for lambda forms first before going to operator parsing
        // This handles the case where an expression starts with an identifier or {
        // that could be a lambda

        let saved = self.pos;

        // Try pattern lambda: { ... }: or name@{ ... }: or { ... }@name:
        if let Some(e) = self.try_pattern_lambda() {
            return e;
        }
        self.pos = saved;

        // Try simple lambda: name:
        if let Some(ident) = self.parse_ident() {
            self.skip_ws();
            if self.peek() == Some(b':') {
                self.pos += 1;
                let body = self.parse_expr_inner();
                return Expr::Lambda {
                    param: LambdaParam::Simple { name: ident, skip: false },
                    body: Box::new(body),
                };
            }
            self.pos = saved;
        }

        self.parse_or()
    }

    /// Try to parse a pattern lambda. Returns None if not a lambda.
    fn try_pattern_lambda(&mut self) -> Option<Expr> {
        self.skip_ws();
        let start = self.pos;

        // Case 1: name@{ ... }: body
        // Case 2: { ... }: body  
        // Case 3: { ... }@name: body

        let at_name_before = {
            let saved = self.pos;
            if let Some(ident) = self.parse_ident() {
                self.skip_ws();
                if self.peek() == Some(b'@') {
                    self.pos += 1;
                    self.skip_ws();
                    Some(ident)
                } else {
                    self.pos = saved;
                    None
                }
            } else {
                None
            }
        };

        if self.peek() != Some(b'{') {
            return None;
        }

        // Look ahead to determine if this is a lambda pattern or an attr set
        if !self.is_lambda_pattern() {
            return None;
        }

        // Parse the pattern
        self.pos += 1; // consume {
        let mut params = Vec::new();
        let mut ellipsis = false;

        loop {
            let before_ws = self.pos;
            self.skip_ws();
            let after_ws = self.pos;

            if self.peek() == Some(b'}') {
                self.pos += 1;
                break;
            }

            if self.starts_with(b"...") {
                self.pos += 3;
                ellipsis = true;
                self.skip_ws();
                if self.peek() == Some(b'}') { self.pos += 1; }
                break;
            }

            // Check for skip comment
            let skip = self.has_deadnix_skip(before_ws, after_ws);

            if let Some(name) = self.parse_ident() {
                self.skip_ws();
                let default = if self.peek() == Some(b'?') {
                    self.pos += 1;
                    self.skip_ws();
                    // Parse default value - it ends at ',' or '}'
                    Some(Box::new(self.parse_default_value()))
                } else {
                    None
                };

                params.push(PatternEntry { name, default, skip });

                self.skip_ws();
                if self.peek() == Some(b',') {
                    self.pos += 1;
                }
            } else {
                break;
            }
        }

        self.skip_ws();

        // Check for @name after pattern
        let at_name_after = if self.peek() == Some(b'@') {
            self.pos += 1;
            self.skip_ws();
            self.parse_ident()
        } else {
            None
        };

        let final_at_name = at_name_before.or(at_name_after);

        self.skip_ws();
        if self.peek() != Some(b':') {
            self.pos = start;
            return None;
        }
        self.pos += 1;

        let body = self.parse_expr_inner();

        Some(Expr::Lambda {
            param: LambdaParam::Pattern {
                at_name: final_at_name,
                at_skip: false,
                params,
                ellipsis,
            },
            body: Box::new(body),
        })
    }

    /// Look ahead from '{' to see if this is a lambda pattern
    /// A lambda pattern has the form: { ident(, ident)* (, ...)? } or { ... }
    fn is_lambda_pattern(&self) -> bool {
        let mut pos = self.pos;
        debug_assert!(self.src[pos] == b'{');
        pos += 1;

        let src = &self.src;

        // Skip whitespace
        let skip_ws_at = |p: &mut usize| {
            while *p < src.len() {
                let b = src[*p];
                if b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' {
                    *p += 1;
                } else if b == b'#' {
                    while *p < src.len() && src[*p] != b'\n' { *p += 1; }
                } else if *p + 1 < src.len() && b == b'/' && src[*p+1] == b'*' {
                    *p += 2;
                    while *p + 1 < src.len() && !(src[*p] == b'*' && src[*p+1] == b'/') {
                        *p += 1;
                    }
                    if *p + 1 < src.len() { *p += 2; }
                } else {
                    break;
                }
            }
        };

        skip_ws_at(&mut pos);

        // Empty pattern {} - could be either, but usually attr set
        if pos < src.len() && src[pos] == b'}' {
            pos += 1;
            skip_ws_at(&mut pos);
            if pos < src.len() && (src[pos] == b':' || src[pos] == b'@') {
                return true;
            }
            return false;
        }

        // Check for ...
        if pos + 2 < src.len() && &src[pos..pos+3] == b"..." {
            pos += 3;
            skip_ws_at(&mut pos);
            if pos < src.len() && src[pos] == b'}' {
                pos += 1;
                skip_ws_at(&mut pos);
                if pos < src.len() && (src[pos] == b':' || src[pos] == b'@') {
                    return true;
                }
            }
            return false;
        }

        // Must start with identifier
        if pos >= src.len() || !(src[pos].is_ascii_alphabetic() || src[pos] == b'_') {
            return false;
        }

        // Skip the first identifier
        while pos < src.len() && (src[pos].is_ascii_alphanumeric() || src[pos] == b'_' || src[pos] == b'\'' || src[pos] == b'-') {
            pos += 1;
        }

        skip_ws_at(&mut pos);

        // After first identifier, we can have:
        // ? default_value (for default value)
        // , (for next param)
        // } (end of pattern)
        // If we see '=', it's an attr set, not a lambda pattern

        if pos < src.len() && src[pos] == b'=' {
            return false; // It's an attr set assignment
        }

        // Skip through the rest of the pattern
        let mut depth = 1;
        while pos < src.len() && depth > 0 {
            match src[pos] {
                b'{' | b'(' | b'[' => { depth += 1; pos += 1; }
                b'}' | b')' | b']' => { 
                    depth -= 1; 
                    pos += 1;
                    if depth == 0 { break; }
                }
                b'"' => {
                    pos += 1;
                    while pos < src.len() && src[pos] != b'"' {
                        if src[pos] == b'\\' { pos += 1; }
                        pos += 1;
                    }
                    if pos < src.len() { pos += 1; }
                }
                _ => { pos += 1; }
            }
        }

        skip_ws_at(&mut pos);

        // After closing }, check for ':' or '@'
        if pos < src.len() && (src[pos] == b':' || src[pos] == b'@') {
            return true;
        }

        false
    }

    fn parse_default_value(&mut self) -> Expr {
        // Parse a default value that ends at ',' or '}' at depth 0
        // We use the full expression parser but need to handle termination
        self.parse_or()
    }

    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        loop {
            self.skip_ws();
            if self.starts_with(b"||") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_and();
                left = Expr::BinOp { op: BinOpKind::Or, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_impl_op();
        loop {
            self.skip_ws();
            if self.starts_with(b"&&") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_impl_op();
                left = Expr::BinOp { op: BinOpKind::And, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_impl_op(&mut self) -> Expr {
        let left = self.parse_eq();
        self.skip_ws();
        if self.starts_with(b"->") {
            self.pos += 2;
            self.skip_ws();
            let right = self.parse_impl_op();
            Expr::BinOp { op: BinOpKind::Impl, left: Box::new(left), right: Box::new(right) }
        } else {
            left
        }
    }

    fn parse_eq(&mut self) -> Expr {
        let mut left = self.parse_cmp();
        loop {
            self.skip_ws();
            if self.starts_with(b"==") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_cmp();
                left = Expr::BinOp { op: BinOpKind::Eq, left: Box::new(left), right: Box::new(right) };
            } else if self.starts_with(b"!=") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_cmp();
                left = Expr::BinOp { op: BinOpKind::NEq, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut left = self.parse_update();
        loop {
            self.skip_ws();
            if self.starts_with(b"<=") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Lte, left: Box::new(left), right: Box::new(right) };
            } else if self.starts_with(b">=") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Gte, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'<') && self.peek_at(1) != Some(b'=') && self.peek_at(1) != Some(b'<') {
                // Make sure it's not a path like <nixpkgs>
                // Simple heuristic: if followed by identifier-char, it might be comparison
                self.pos += 1;
                self.skip_ws();
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Lt, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'>') && self.peek_at(1) != Some(b'=') {
                self.pos += 1;
                self.skip_ws();
                let right = self.parse_update();
                left = Expr::BinOp { op: BinOpKind::Gt, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_update(&mut self) -> Expr {
        let mut left = self.parse_not();
        loop {
            self.skip_ws();
            if self.starts_with(b"//") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_not();
                left = Expr::BinOp { op: BinOpKind::Update, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_not(&mut self) -> Expr {
        self.skip_ws();
        if self.peek() == Some(b'!') && self.peek_at(1) != Some(b'=') {
            self.pos += 1;
            self.skip_ws();
            let expr = self.parse_not();
            Expr::UnaryOp { op: UnaryOpKind::Not, expr: Box::new(expr) }
        } else {
            self.parse_concat()
        }
    }

    fn parse_concat(&mut self) -> Expr {
        let mut left = self.parse_add();
        loop {
            self.skip_ws();
            if self.starts_with(b"++") {
                self.pos += 2;
                self.skip_ws();
                let right = self.parse_concat(); // right associative
                left = Expr::BinOp { op: BinOpKind::Concat, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_add(&mut self) -> Expr {
        let mut left = self.parse_mul();
        loop {
            self.skip_ws();
            if self.peek() == Some(b'+') && self.peek_at(1) != Some(b'+') {
                self.pos += 1;
                self.skip_ws();
                let right = self.parse_mul();
                left = Expr::BinOp { op: BinOpKind::Add, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'-') {
                // subtraction: needs space or next is atom-starting char
                let next = self.peek_at(1);
                if next.map_or(false, |b| b == b' ' || b == b'\t' || b == b'\n' ||
                    b.is_ascii_alphanumeric() || b == b'"' || b == b'(' || b == b'{' || b == b'[' || b == b'_' || b == b'\'') {
                    self.pos += 1;
                    self.skip_ws();
                    let right = self.parse_mul();
                    left = Expr::BinOp { op: BinOpKind::Sub, left: Box::new(left), right: Box::new(right) };
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        left
    }

    fn parse_mul(&mut self) -> Expr {
        let mut left = self.parse_neg();
        loop {
            self.skip_ws();
            if self.peek() == Some(b'*') {
                self.pos += 1;
                self.skip_ws();
                let right = self.parse_neg();
                left = Expr::BinOp { op: BinOpKind::Mul, left: Box::new(left), right: Box::new(right) };
            } else if self.peek() == Some(b'/') && self.peek_at(1) != Some(b'/') && self.peek_at(1) != Some(b'*') {
                self.pos += 1;
                self.skip_ws();
                let right = self.parse_neg();
                left = Expr::BinOp { op: BinOpKind::Div, left: Box::new(left), right: Box::new(right) };
            } else {
                break;
            }
        }
        left
    }

    fn parse_neg(&mut self) -> Expr {
        self.skip_ws();
        if self.peek() == Some(b'-') && self.peek_at(1).map_or(false, |b| !b.is_ascii_digit()) {
            // Hmm, this is tricky - "-1" should be int, but "- x" is subtract
            // We only do unary neg if the next is NOT a digit (that's handled in parse_atom)
            // Actually in Nix, - as unary is only "- expr" with space
            // Let's skip this for now and handle in parse_atom
            self.parse_hasattr()
        } else {
            self.parse_hasattr()
        }
    }

    fn parse_hasattr(&mut self) -> Expr {
        let expr = self.parse_apply();
        self.skip_ws();
        if self.peek() == Some(b'?') && self.peek_at(1) != Some(b'>') {
            self.pos += 1;
            self.skip_ws();
            let attr = self.parse_attrpath();
            Expr::HasAttr { expr: Box::new(expr), attr }
        } else {
            expr
        }
    }

    fn parse_apply(&mut self) -> Expr {
        let mut func = self.parse_select();
        loop {
            self.skip_ws();
            if self.can_start_atom_lookahead() {
                let arg = self.parse_select();
                func = Expr::Apply { func: Box::new(func), arg: Box::new(arg) };
            } else {
                break;
            }
        }
        func
    }

    fn can_start_atom_lookahead(&self) -> bool {
        match self.peek() {
            None => false,
            Some(b'(') | Some(b'"') => true,
            Some(b'\'') => self.peek_at(1) == Some(b'\''),
            Some(b'[') => true,
            Some(b'{') => self.is_lambda_pattern(),
            Some(b'<') => {
                // <nixpkgs> style path
                let next = self.peek_at(1);
                next.map_or(false, |n| n.is_ascii_alphanumeric() || n == b'_' || n == b'/')
            }
            Some(b'.') => {
                let next = self.peek_at(1);
                next == Some(b'/') || next == Some(b'.')
            }
            Some(b'/') => {
                let next = self.peek_at(1);
                next.map_or(false, |n| n != b'/' && n != b'*' && (n.is_ascii_alphanumeric() || n == b'_'))
            }
            Some(b'~') => true,
            Some(b'-') => self.peek_at(1).map_or(false, |b| b.is_ascii_digit()),
            Some(b) if b.is_ascii_digit() => true,
            Some(b) if b.is_ascii_alphabetic() || b == b'_' => {
                // Identifier - check if it's a keyword that doesn't start an expression
                // that can be used as function argument
                let mut end = self.pos;
                let src = &self.src;
                while end < src.len() {
                    let c = src[end];
                    if c.is_ascii_alphanumeric() || c == b'_' || c == b'\'' || c == b'-' {
                        end += 1;
                    } else {
                        break;
                    }
                }
                let word = std::str::from_utf8(&src[self.pos..end]).unwrap_or("");
                // These words cannot start a new argument expression in this context
                !matches!(word, "then" | "else" | "in" | "rec")
                // Note: "let", "if", "with", "assert" CAN start nested expressions
                // but we need to be careful about parsing them as function arguments
                // Actually they should be fine since they're valid expressions
            }
            _ => false,
        }
    }

    fn parse_select(&mut self) -> Expr {
        let mut expr = self.parse_atom();
        loop {
            self.skip_ws();
            if self.peek() == Some(b'.') {
                let next = self.peek_at(1);
                // Could be attribute access if next char is ident, '"', or '$'
                if next.map_or(false, |b| b.is_ascii_alphanumeric() || b == b'_' || b == b'"' || b == b'$') {
                    self.pos += 1; // consume '.'
                    self.skip_ws();
                    let attr = self.parse_attrpath();
                    self.skip_ws();
                    // Check for 'or' keyword
                    let default = if self.check_keyword("or") {
                        self.pos += 2;
                        self.skip_ws();
                        Some(Box::new(self.parse_select()))
                    } else {
                        None
                    };
                    expr = Expr::Select { expr: Box::new(expr), attr, default };
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        expr
    }

    fn check_keyword(&self, kw: &str) -> bool {
        let kw_bytes = kw.as_bytes();
        if !self.src[self.pos..].starts_with(kw_bytes) {
            return false;
        }
        let end = self.pos + kw_bytes.len();
        if end >= self.src.len() {
            return true;
        }
        let next = self.src[end];
        !(next.is_ascii_alphanumeric() || next == b'_' || next == b'\'' || next == b'-')
    }

    fn parse_attrpath(&mut self) -> AttrPath {
        let mut path = Vec::new();
        loop {
            self.skip_ws();
            if self.peek() == Some(b'"') {
                // String key - may have interpolations
                let parts = self.parse_string_parts();
                let plain = parts.iter().all(|p| matches!(p, StringPart::Literal(_)));
                if plain {
                    let s: String = parts.into_iter().filter_map(|p| {
                        if let StringPart::Literal(s) = p { Some(s) } else { None }
                    }).collect();
                    path.push(AttrPathComponent::StringKey(s, vec![]));
                } else {
                    path.push(AttrPathComponent::StringKey(String::new(), parts));
                }
            } else if self.peek() == Some(b'$') && self.peek_at(1) == Some(b'{') {
                self.pos += 2;
                let expr = self.parse_expr();
                self.skip_ws();
                if self.peek() == Some(b'}') { self.pos += 1; }
                path.push(AttrPathComponent::Dynamic(Box::new(expr)));
            } else if let Some(ident) = self.parse_ident() {
                path.push(AttrPathComponent::Ident(ident));
            } else {
                break;
            }

            self.skip_ws();
            if self.peek() == Some(b'.') {
                let next = self.peek_at(1);
                if next.map_or(false, |b| b.is_ascii_alphanumeric() || b == b'_' || b == b'"' || b == b'$') {
                    self.pos += 1;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        path
    }

    fn parse_string_parts(&mut self) -> Vec<StringPart> {
        if self.peek() != Some(b'"') { return vec![]; }
        self.pos += 1;
        let mut parts = Vec::new();
        let mut current = String::new();

        while self.pos < self.src.len() {
            match self.src[self.pos] {
                b'"' => { self.pos += 1; break; }
                b'\\' => {
                    self.pos += 1;
                    if self.pos < self.src.len() {
                        let c = self.src[self.pos];
                        current.push(match c {
                            b'n' => '\n',
                            b't' => '\t',
                            b'r' => '\r',
                            _ => c as char,
                        });
                        self.pos += 1;
                    }
                }
                b'$' if self.peek_at(1) == Some(b'{') => {
                    if !current.is_empty() {
                        parts.push(StringPart::Literal(std::mem::take(&mut current)));
                    }
                    self.pos += 2;
                    let expr = self.parse_expr();
                    self.skip_ws();
                    if self.peek() == Some(b'}') { self.pos += 1; }
                    parts.push(StringPart::Interpolation(Box::new(expr)));
                }
                b => {
                    current.push(b as char);
                    self.pos += 1;
                }
            }
        }
        if !current.is_empty() {
            parts.push(StringPart::Literal(current));
        }
        parts
    }

    fn parse_atom(&mut self) -> Expr {
        self.skip_ws();

        match self.peek() {
            None => Expr::Error,
            Some(b'(') => {
                self.pos += 1;
                let expr = self.parse_expr();
                self.skip_ws();
                if self.peek() == Some(b')') { self.pos += 1; }
                expr
            }
            Some(b'"') => {
                let parts = self.parse_string_parts();
                Expr::Str { parts }
            }
            Some(b'\'') if self.peek_at(1) == Some(b'\'') => {
                self.parse_indented_string()
            }
            Some(b'[') => {
                self.pos += 1;
                let mut items = Vec::new();
                loop {
                    self.skip_ws();
                    if self.peek() == Some(b']') { self.pos += 1; break; }
                    if self.peek().is_none() { break; }
                    items.push(self.parse_select());
                }
                Expr::List(items)
            }
            Some(b'{') => {
                // Must be an attr set (pattern lambdas handled above)
                self.parse_attr_set(false)
            }
            Some(b) if b.is_ascii_digit() => {
                self.parse_number()
            }
            Some(b'-') if self.peek_at(1).map_or(false, |b| b.is_ascii_digit()) => {
                self.pos += 1;
                let n = self.parse_number();
                match n {
                    Expr::Int(i) => Expr::Int(-i),
                    Expr::Float(f) => Expr::Float(-f),
                    _ => n,
                }
            }
            Some(b'/') | Some(b'.') | Some(b'~') | Some(b'<') => {
                self.parse_path()
            }
            Some(_) => {
                let ident = match self.parse_ident() {
                    Some(i) => i,
                    None => {
                        // Skip unknown character
                        self.pos += 1;
                        return Expr::Error;
                    }
                };

                match ident.name.as_str() {
                    "true" => Expr::Bool(true),
                    "false" => Expr::Bool(false),
                    "null" => Expr::Null,
                    "rec" => {
                        self.skip_ws();
                        if self.peek() == Some(b'{') {
                            self.parse_attr_set(true)
                        } else {
                            Expr::Var(ident)
                        }
                    }
                    "let" => self.parse_let(),
                    "if" => self.parse_if(),
                    "with" => self.parse_with(),
                    "assert" => self.parse_assert(),
                    _ => Expr::Var(ident),
                }
            }
        }
    }

    fn parse_number(&mut self) -> Expr {
        let start = self.pos;
        while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.pos < self.src.len() && self.src[self.pos] == b'.' {
            let next = self.peek_at(1);
            if next.map_or(false, |b| b.is_ascii_digit()) {
                self.pos += 1;
                while self.pos < self.src.len() && self.src[self.pos].is_ascii_digit() {
                    self.pos += 1;
                }
                let s = std::str::from_utf8(&self.src[start..self.pos]).unwrap();
                return Expr::Float(s.parse().unwrap_or(0.0));
            }
        }
        let s = std::str::from_utf8(&self.src[start..self.pos]).unwrap();
        Expr::Int(s.parse().unwrap_or(0))
    }

    fn parse_path(&mut self) -> Expr {
        let start = self.pos;
        if self.peek() == Some(b'~') { self.pos += 1; }
        if self.peek() == Some(b'<') {
            self.pos += 1;
            while self.pos < self.src.len() && self.src[self.pos] != b'>' { self.pos += 1; }
            if self.pos < self.src.len() { self.pos += 1; }
            return Expr::Path(std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string());
        }
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            if b.is_ascii_alphanumeric() || b == b'/' || b == b'.' || b == b'_' || b == b'-' {
                self.pos += 1;
            } else if b == b'$' && self.peek_at(1) == Some(b'{') {
                self.pos += 2;
                let _ = self.parse_expr();
                self.skip_ws();
                if self.peek() == Some(b'}') { self.pos += 1; }
            } else {
                break;
            }
        }
        Expr::Path(std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string())
    }

    fn parse_indented_string(&mut self) -> Expr {
        self.pos += 2; // consume ''
        let mut parts = Vec::new();
        let mut current = String::new();

        loop {
            if self.pos >= self.src.len() { break; }
            if self.starts_with(b"''") {
                let after = self.src.get(self.pos + 2).copied();
                match after {
                    Some(b'$') | Some(b'\\') | Some(b'\'') => {
                        current.push(after.unwrap() as char);
                        self.pos += 3;
                        continue;
                    }
                    _ => {
                        self.pos += 2;
                        break;
                    }
                }
            }
            if self.src[self.pos] == b'$' && self.peek_at(1) == Some(b'{') {
                if !current.is_empty() {
                    parts.push(StringPart::Literal(std::mem::take(&mut current)));
                }
                self.pos += 2;
                let expr = self.parse_expr();
                self.skip_ws();
                if self.peek() == Some(b'}') { self.pos += 1; }
                parts.push(StringPart::Interpolation(Box::new(expr)));
            } else {
                current.push(self.src[self.pos] as char);
                self.pos += 1;
            }
        }
        if !current.is_empty() {
            parts.push(StringPart::Literal(current));
        }
        Expr::IndentedStr { parts }
    }

    pub fn parse_attr_set(&mut self, recursive: bool) -> Expr {
        if self.peek() != Some(b'{') { return Expr::Error; }
        self.pos += 1;
        let mut entries = Vec::new();

        loop {
            self.skip_ws();
            if self.peek() == Some(b'}') { self.pos += 1; break; }
            if self.peek().is_none() { break; }

            // Check for inherit
            let saved = self.pos;
            if let Some(ident) = self.parse_ident() {
                if ident.name == "inherit" {
                    self.skip_ws();
                    let from = if self.peek() == Some(b'(') {
                        self.pos += 1;
                        let e = self.parse_expr();
                        self.skip_ws();
                        if self.peek() == Some(b')') { self.pos += 1; }
                        Some(Box::new(e))
                    } else {
                        None
                    };

                    let mut names = Vec::new();
                    loop {
                        self.skip_ws();
                        if self.peek() == Some(b';') || self.peek() == Some(b'}') { break; }
                        if let Some(n) = self.parse_ident() {
                            names.push(n);
                        } else {
                            break;
                        }
                    }

                    self.skip_ws();
                    if self.peek() == Some(b';') { self.pos += 1; }

                    // Create entries for each name
                    for name in &names {
                        let path = vec![AttrPathComponent::Ident(name.clone())];
                        let value = if let Some(ref f) = from {
                            Expr::Select {
                                expr: Box::new(*f.clone()),
                                attr: vec![AttrPathComponent::Ident(name.clone())],
                                default: None,
                            }
                        } else {
                            Expr::Var(name.clone())
                        };
                        entries.push(AttrEntry {
                            path,
                            value: Box::new(value),
                            inherit_from: from.as_ref().map(|e| Box::new(*e.clone())),
                        });
                    }
                    continue;
                }
                self.pos = saved;
            }

            // Parse attr path = expr ;
            let path = self.parse_attrpath();
            if path.is_empty() {
                self.pos += 1; // skip unknown
                continue;
            }

            self.skip_ws();
            if self.peek() == Some(b'=') {
                self.pos += 1;
                let value = self.parse_expr();
                self.skip_ws();
                if self.peek() == Some(b';') { self.pos += 1; }
                entries.push(AttrEntry { path, value: Box::new(value), inherit_from: None });
            } else {
                break;
            }
        }

        Expr::AttrSet { recursive, entries }
    }

    pub fn parse_let(&mut self) -> Expr {
        let mut bindings = Vec::new();

        loop {
            let before_ws = self.pos;
            self.skip_ws();
            let after_ws = self.pos;

            if self.peek().is_none() { break; }

            // Check for "in" keyword
            if self.check_keyword("in") {
                self.pos += 2;
                break;
            }

            // Get skip comment status
            let skip = self.has_deadnix_skip(before_ws, after_ws);

            let saved = self.pos;
            if let Some(ident) = self.parse_ident() {
                if ident.name == "inherit" {
                    let from = {
                        self.skip_ws();
                        if self.peek() == Some(b'(') {
                            self.pos += 1;
                            let e = self.parse_expr();
                            self.skip_ws();
                            if self.peek() == Some(b')') { self.pos += 1; }
                            Some(Box::new(e))
                        } else {
                            None
                        }
                    };

                    let mut names = Vec::new();
                    loop {
                        self.skip_ws();
                        if self.peek() == Some(b';') { break; }
                        if self.peek().is_none() { break; }
                        if self.check_keyword("in") { break; }
                        if let Some(n) = self.parse_ident() {
                            names.push(n);
                        } else {
                            break;
                        }
                    }
                    self.skip_ws();
                    if self.peek() == Some(b';') { self.pos += 1; }

                    bindings.push(LetBinding::Inherit { from, names, skip });
                    continue;
                }

                // Plain binding: name = expr ;
                self.skip_ws();
                if self.peek() == Some(b'=') {
                    self.pos += 1;
                    let value = self.parse_expr();
                    self.skip_ws();
                    if self.peek() == Some(b';') { self.pos += 1; }
                    bindings.push(LetBinding::Plain { name: ident, value: Box::new(value), skip });
                    continue;
                }

                // Not a binding, restore and break
                self.pos = saved;
                break;
            } else {
                break;
            }
        }

        self.skip_ws();
        let body = self.parse_expr();

        Expr::Let { bindings, body: Box::new(body) }
    }

    fn parse_if(&mut self) -> Expr {
        self.skip_ws();
        let cond = self.parse_expr();
        self.skip_ws();
        // expect "then"
        if self.check_keyword("then") { self.pos += 4; }
        self.skip_ws();
        let then = self.parse_expr();
        self.skip_ws();
        if self.check_keyword("else") { self.pos += 4; }
        self.skip_ws();
        let else_ = self.parse_expr();
        Expr::If { cond: Box::new(cond), then: Box::new(then), else_: Box::new(else_) }
    }

    fn parse_with(&mut self) -> Expr {
        self.skip_ws();
        let namespace = self.parse_expr();
        self.skip_ws();
        if self.peek() == Some(b';') { self.pos += 1; }
        self.skip_ws();
        let body = self.parse_expr();
        Expr::With { namespace: Box::new(namespace), body: Box::new(body) }
    }

    fn parse_assert(&mut self) -> Expr {
        self.skip_ws();
        let cond = self.parse_expr();
        self.skip_ws();
        if self.peek() == Some(b';') { self.pos += 1; }
        self.skip_ws();
        let body = self.parse_expr();
        Expr::Assert { cond: Box::new(cond), body: Box::new(body) }
    }
}

pub fn parse(src: &str) -> Expr {
    let mut p = Parser::new(src);
    p.parse_expr()
}
