# Fix collect_used_in_expr for AttrSet to handle interpolated string keys
cat > /tmp/fix_attrset.py << 'EOF'
import re

with open('/workspace/src/analysis.rs', 'r') as f:
    content = f.read()

# Fix the AttrSet case in collect_used_in_expr
old = '''        Expr::AttrSet { entries, .. } => {
            for entry in entries {
                for comp in &entry.path {
                    if let AttrPathComponent::Dynamic(e) = comp {
                        collect_used_in_expr(e, used);
                    }
                }
                collect_used_in_expr(&entry.value, used);
            }
        }'''

new = '''        Expr::AttrSet { entries, .. } => {
            for entry in entries {
                for comp in &entry.path {
                    match comp {
                        AttrPathComponent::Dynamic(e) => {
                            collect_used_in_expr(e, used);
                        }
                        AttrPathComponent::StringKey(_, parts) => {
                            for part in parts {
                                if let StringPart::Interpolation(e) = part {
                                    collect_used_in_expr(e, used);
                                }
                            }
                        }
                        _ => {}
                    }
                }
                collect_used_in_expr(&entry.value, used);
            }
        }'''

content = content.replace(old, new)

with open('/workspace/src/analysis.rs', 'w') as f:
    f.write(content)

print("Fixed AttrSet case")
EOF
