# The issue is in how we build the pattern when removing items.
# The original "{ unusedArg2, x ? args.y, ... }@args: used1 + x;"
# After removing unusedArg2: "{ x ? args.y, ... }@args: used1 + x;"
# But our code is generating "args@{ x ? args.y, ... }@args: used1 + x;"
# 
# The bug is in build_new_pattern: we're adding "args@" at the front even when
# at_name is the AFTER-pattern binding.
# 
# Looking at the original pattern: { unusedArg2, x ? args.y, ... }@args
# The @args is AFTER the pattern. In my code:
# at_name_before = None (no name before {)
# at_name_after = Some(Ident { name: "args", ... })
# final_at_name = at_name_after = Some("args")
# 
# In build_new_pattern:
# "if let Some(at) = at_name {
#     result.push_str(&at.name);
#     result.push('@');
# }"
# This always puts the @ name BEFORE the pattern!
# But in the original, it was AFTER.
# 
# I need to track whether the @ was before or after and preserve that.

# Also the issue with "{ x ? args.y" -> the default value text extraction is failing.
# Let me check if the default value is correctly extracted.

# Actually the bigger issue for now: the @ positioning.
# Let me fix build_new_pattern to handle at_name position.
# 
# I'll look at the AST to see where the @ name position is.
# In my PatternEntry, there's no way to tell if @ was before or after.
# I need to store this information in LambdaParam::Pattern.

# Let me add an 'at_before' flag to LambdaParam::Pattern

cat > /tmp/fix_at.py << 'EOF'
with open('/workspace/src/nix_parse.rs', 'r') as f:
    content = f.read()

# Add at_before field to LambdaParam::Pattern
old_pattern = '''    Pattern {
        at_name: Option<Ident>,
        at_skip: bool,
        params: Vec<PatternEntry>,
        ellipsis: bool,
    },'''

new_pattern = '''    Pattern {
        at_name: Option<Ident>,
        at_before: bool,  // true if @ binding is before the pattern (name@{...}), false if after ({...}@name)
        at_skip: bool,
        params: Vec<PatternEntry>,
        ellipsis: bool,
    },'''

content = content.replace(old_pattern, new_pattern)

# Fix try_pattern_lambda to track at_before
old_final = '''        let final_at_name = at_name_before.or(at_name_after);

        self.skip_ws();
        if self.peek() != Some(b\':\') {
            self.pos = start;
            return None;
        }
        self.pos += 1;

        let body = self.parse_expr_inner();

        Some(Expr::Lambda {
            param: LambdaParam::Pattern {
                at_name: final_at_name,
                at_skip: false,
                params,
                ellipsis,
            },
            body: Box::new(body),
        })'''

new_final = '''        let at_before = at_name_before.is_some();
        let final_at_name = at_name_before.or(at_name_after);

        self.skip_ws();
        if self.peek() != Some(b\':\') {
            self.pos = start;
            return None;
        }
        self.pos += 1;

        let body = self.parse_expr_inner();

        Some(Expr::Lambda {
            param: LambdaParam::Pattern {
                at_name: final_at_name,
                at_before,
                at_skip: false,
                params,
                ellipsis,
            },
            body: Box::new(body),
        })'''

content = content.replace(old_final, new_final)

with open('/workspace/src/nix_parse.rs', 'w') as f:
    f.write(content)

print("Added at_before field")
